01; // 1% safety margin\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":418},{"name":"yMin","defaultValue":"computed(() => {\\n    const items = this.heikinAshiData();\\n    if (items.length === 0) return 0;\\n    const lows = items.map(d => d.low);\\n    const minVal = Math.min(...lows);\\n    return minVal * 0.99; // 1% safety margin\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":410},{"name":"yTicks","defaultValue":"computed(() => niceTicks(this.yMin(), this.yMax(), 5))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":426}],"methodsClass":[{"name":"candleWidth","args":[],"optional":false,"returnType":"number","typeParameters":[],"line":438,"deprecated":false,"deprecationMessage":""},{"name":"exportToCsv","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":521,"deprecated":false,"deprecationMessage":""},{"name":"exportToJson","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":533,"deprecated":false,"deprecationMessage":""},{"name":"exportToPdf","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":543,"deprecated":false,"deprecationMessage":""},{"name":"exportToSvg","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":539,"deprecated":false,"deprecationMessage":""},{"name":"formatDate","args":[{"name":"d","type":"string | Date","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"string","typeParameters":[],"line":507,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"d","type":"string | Date","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onCandleHover","args":[{"name":"event","type":"MouseEvent","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""},{"name":"item","type":"HeikinAshiCalculatedItem","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""},{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":489,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"event","type":"MouseEvent","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}},{"name":"item","type":"HeikinAshiCalculatedItem","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}},{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onExport","args":[{"name":"type","type":"ExportFormat","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":514,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"type","type":"ExportFormat","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"shouldShowXLabel","args":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"boolean","typeParameters":[],"line":481,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"xPos","args":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"number","typeParameters":[],"line":428,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"yPos","args":[{"name":"y","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"number","typeParameters":[],"line":434,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"y","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]}],"deprecated":false,"deprecationMessage":"","hostBindings":[],"hostListeners":[],"standalone":true,"imports":[{"name":"ChartExportMenuComponent","type":"component"}],"description":"","rawdescription":"\\n","type":"component","sourceCode":"import {\\n  Component, ChangeDetectionStrategy, input, computed, signal,\\n  ElementRef, inject, DestroyRef, viewChild\\n} from \'@angular/core\';\\nimport { ChartExportService } from \'../shared/chart-export.service\';\\nimport { ChartExportMenuComponent } from \'../shared/chart-export-menu.component\';\\nimport type { ExportFormat } from \'../shared/chart-export-menu.component\';\\nimport { niceTicks, scale, fmtNum, CHART_COLORS , generateUniqueId } from \'../shared/chart-utils\';\\n\\nexport interface CandlestickItem {\\n  date: string | Date;\\n  open: number;\\n  high: number;\\n  low: number;\\n  close: number;\\n}\\n\\ninterface HeikinAshiCalculatedItem {\\n  date: string | Date;\\n  open: number;\\n  high: number;\\n  low: number;\\n  close: number;\\n  original: CandlestickItem;\\n}\\n\\n@Component({\\n  selector: \'ngx-heikin-ashi-chart\',\\n  standalone: true,\\n  imports: [ChartExportMenuComponent],\\n  changeDetection: ChangeDetectionStrategy.OnPush,\\n  template: `\\n    <div class=\\"ngx-heikin-ashi-chart\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n      \x3c!-- Toolbar with Export option --\x3e\\n      <div class=\\"chart-header\\" (mousemove)=\\"$event.stopPropagation()\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n        <div class=\\"chart-title-space\\"></div>\\n        @if (showExport()) {\\n          <ngx-chart-export-menu (exportClicked)=\\"onExport($event)\\" />\\n        }\\n      </div>\\n\\n      <div class=\\"chart-svg-container\\" #container>\\n        <svg\\n          #svgEl\\n          [attr.width]=\\"\'100%\'\\"\\n          [attr.height]=\\"height()\\"\\n          class=\\"chart-svg\\"\\n        >\\n          <defs>\\n            <linearGradient [id]=\\"instanceId + \'-ha-bullish-grad\'\\" x1=\\"0\\" y1=\\"0\\" x2=\\"0\\" y2=\\"1\\">\\n              <stop offset=\\"0%\\" [attr.stop-color]=\\"bullishColor()\\" />\\n              <stop offset=\\"100%\\" [attr.stop-color]=\\"bullishColor()\\" stop-opacity=\\"0.8\\" />\\n            </linearGradient>\\n            <linearGradient [id]=\\"instanceId + \'-ha-bearish-grad\'\\" x1=\\"0\\" y1=\\"0\\" x2=\\"0\\" y2=\\"1\\">\\n              <stop offset=\\"0%\\" [attr.stop-color]=\\"bearishColor()\\" />\\n              <stop offset=\\"100%\\" [attr.stop-color]=\\"bearishColor()\\" stop-opacity=\\"0.8\\" />\\n            </linearGradient>\\n          </defs>\\n\\n          <g [attr.transform]=\\"\'translate(\' + PAD_LEFT + \',\' + PAD_TOP + \')\'\\">\\n            \x3c!-- Grid Lines (Horizontal) --\x3e\\n            @if (showGrid()) {\\n              @for (tick of yTicks(); track tick) {\\n                <line\\n                  [attr.x1]=\\"0\\"\\n                  [attr.x2]=\\"innerW()\\"\\n                  [attr.y1]=\\"yPos(tick)\\"\\n                  [attr.y2]=\\"yPos(tick)\\"\\n                  stroke=\\"var(--ngx-chart-grid, #ebedf0)\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                />\\n              }\\n            }\\n\\n            \x3c!-- Y-Axis Labels --\x3e\\n            @if (showLabels()) {\\n              @for (tick of yTicks(); track tick) {\\n                <text\\n                  x=\\"-10\\"\\n                  [attr.y]=\\"yPos(tick) + 4\\"\\n                  class=\\"axis-label y\\"\\n                  text-anchor=\\"end\\"\\n                >{{ fmtNum(tick) }}</text>\\n              }\\n            }\\n\\n            \x3c!-- X-Axis Labels --\x3e\\n            @if (showLabels()) {\\n              @for (item of heikinAshiData(); track $index; let i = $index) {\\n                @if (shouldShowXLabel(i)) {\\n                  <text\\n                    [attr.x]=\\"xPos(i) + candleWidth() / 2\\"\\n                    [attr.y]=\\"innerH() + 20\\"\\n                    class=\\"axis-label x\\"\\n                    text-anchor=\\"middle\\"\\n                  >{{ formatDate(item.date) }}</text>\\n                }\\n              }\\n            }\\n\\n            \x3c!-- Active Crosshair --\x3e\\n            @if (hoveredIndex() !== null) {\\n              @if (computedCandles()[hoveredIndex()!]; as candle) {\\n                <line\\n                  [attr.x1]=\\"0\\"\\n                  [attr.x2]=\\"innerW()\\"\\n                  [attr.y1]=\\"candle.yClose\\"\\n                  [attr.y2]=\\"candle.yClose\\"\\n                  stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n                  stroke-width=\\"1.2\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                  class=\\"crosshair-line\\"\\n                />\\n                <line\\n                  [attr.x1]=\\"candle.centerX\\"\\n                  [attr.x2]=\\"candle.centerX\\"\\n                  [attr.y1]=\\"0\\"\\n                  [attr.y2]=\\"innerH()\\"\\n                  stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n                  stroke-width=\\"1.2\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                  class=\\"crosshair-line\\"\\n                />\\n              }\\n            }\\n\\n            \x3c!-- Heikin-Ashi Candles --\x3e\\n            @for (candle of computedCandles(); track $index; let i = $index) {\\n              \x3c!-- Wick Line (High to Low) --\x3e\\n              <line\\n                [attr.x1]=\\"candle.centerX\\"\\n                [attr.x2]=\\"candle.centerX\\"\\n                [attr.y1]=\\"candle.yHigh\\"\\n                [attr.y2]=\\"candle.yLow\\"\\n                [attr.stroke]=\\"candle.color\\"\\n                stroke-width=\\"1.5\\"\\n                class=\\"candle-wick\\"\\n              />\\n\\n              \x3c!-- Candle Body Rect (Open to Close) --\x3e\\n              <rect\\n                [attr.x]=\\"candle.x\\"\\n                [attr.y]=\\"candle.y\\"\\n                [attr.width]=\\"candle.width\\"\\n                [attr.height]=\\"candle.rectH\\"\\n                [attr.fill]=\\"candle.isBullish ? \'url(#\' + instanceId + \'-ha-bullish-grad)\' : \'url(#\' + instanceId + \'-ha-bearish-grad)\'\\"\\n                [attr.stroke]=\\"candle.color\\"\\n                stroke-width=\\"1\\"\\n                class=\\"candle-rect\\"\\n                [class.hovered]=\\"hoveredIndex() === i\\"\\n                [style.transform-origin]=\\"candle.centerX + \'px \' + candle.yOpen + \'px\'\\"\\n                [style.animation-delay]=\\"i * 0.02 + \'s\'\\"\\n                (mouseenter)=\\"onCandleHover($event, candle.raw, i)\\"\\n                (mousemove)=\\"onCandleHover($event, candle.raw, i)\\"\\n              />\\n            }\\n\\n            \x3c!-- Base axes borders --\x3e\\n            <line x1=\\"0\\" [attr.x2]=\\"innerW()\\" [attr.y1]=\\"innerH()\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n            <line x1=\\"0\\" x2=\\"0\\" y1=\\"0\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n          </g>\\n        </svg>\\n\\n        \x3c!-- Tooltip --\x3e\\n        @if (tooltip(); as t) {\\n          <div class=\\"chart-tooltip\\" [style.left.px]=\\"t.x\\" [style.top.px]=\\"t.y\\">\\n            <div class=\\"tooltip-header\\">{{ formatDate(t.date) }}</div>\\n            <div class=\\"tooltip-body\\">\\n              <div class=\\"tooltip-direction\\" [style.color]=\\"t.isBullish ? \'#10b981\' : \'#ef4444\'\\">\\n                <strong>{{ t.isBullish ? \'Bullish Trend\' : \'Bearish Trend\' }}</strong>\\n              </div>\\n              \x3c!-- Tabular Tooltip for comparisons --\x3e\\n              <div class=\\"tooltip-columns\\">\\n                <div class=\\"tooltip-col\\">\\n                  <div class=\\"col-title\\">Original</div>\\n                  <div class=\\"tooltip-val\\"><span>O:</span> <strong>{{ fmtNum(t.orig.open) }}</strong></div>\\n                  <div class=\\"tooltip-val\\"><span>H:</span> <strong>{{ fmtNum(t.orig.high) }}</strong></div>\\n                  <div class=\\"tooltip-val\\"><span>L:</span> <strong>{{ fmtNum(t.orig.low) }}</strong></div>\\n                  <div class=\\"tooltip-val\\"><span>C:</span> <strong>{{ fmtNum(t.orig.close) }}</strong></div>\\n                </div>\\n                <div class=\\"tooltip-col bordered\\">\\n                  <div class=\\"col-title\\" style=\\"color: #38bdf8;\\">Heikin-Ashi</div>\\n                  <div class=\\"tooltip-val\\"><span>O:</span> <strong>{{ fmtNum(t.ha.open) }}</strong></div>\\n                  <div class=\\"tooltip-val\\"><span>H:</span> <strong>{{ fmtNum(t.ha.high) }}</strong></div>\\n                  <div class=\\"tooltip-val\\"><span>L:</span> <strong>{{ fmtNum(t.ha.low) }}</strong></div>\\n                  <div class=\\"tooltip-val\\"><span>C:</span> <strong>{{ fmtNum(t.ha.close) }}</strong></div>\\n                </div>\\n              </div>\\n            </div>\\n          </div>\\n        }\\n      </div>\\n    </div>\\n  `,\\n  styles: [`\\n    :host {\\n      display: block;\\n      width: 100%;\\n    }\\n    .ngx-heikin-ashi-chart {\\n      position: relative;\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n    }\\n    .chart-svg-container {\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .axis-label {\\n      font-size: 10px;\\n      fill: #64748b;\\n      font-weight: 500;\\n    }\\n\\n    @keyframes candleGrow {\\n      from { transform: scaleY(0); opacity: 0; }\\n      to { transform: scaleY(1); opacity: 1; }\\n    }\\n\\n    .candle-rect {\\n      cursor: pointer;\\n      transition: fill 0.15s, opacity 0.15s, stroke-width 0.15s, filter 0.15s;\\n      animation: candleGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;\\n    }\\n    .candle-rect.hovered {\\n      filter: brightness(1.05) drop-shadow(0 4px 10px rgba(0,0,0,0.18));\\n      stroke-width: 1.5px;\\n    }\\n    .crosshair-line {\\n      pointer-events: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.94));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 11px;\\n      z-index: 100;\\n      min-width: 210px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      transition: left 0.08s ease-out, top 0.08s ease-out;\\n    }\\n    .tooltip-header {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tooltip-direction {\\n      font-size: 10px;\\n      font-weight: 700;\\n      margin-bottom: 8px;\\n      text-transform: uppercase;\\n      letter-spacing: 0.3px;\\n    }\\n    .tooltip-columns {\\n      display: flex;\\n      gap: 12px;\\n    }\\n    .tooltip-col {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 2px;\\n      flex: 1;\\n    }\\n    .tooltip-col.bordered {\\n      border-left: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-left: 12px;\\n    }\\n    .col-title {\\n      font-weight: 600;\\n      font-size: 9.5px;\\n      color: rgba(255, 255, 255, 0.5);\\n      text-transform: uppercase;\\n      margin-bottom: 4px;\\n    }\\n    .tooltip-val {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: 8px;\\n      color: rgba(248, 250, 252, 0.85);\\n    }\\n    .tooltip-val span {\\n      color: rgba(255, 255, 255, 0.55);\\n    }\\n    .tooltip-val strong {\\n      color: #f8fafc;\\n      font-family: monospace;\\n      font-weight: 700;\\n    }\\n\\n    /* Export styles removed */\\n    .chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }\\n  `]\\n})\\nexport class HeikinAshiChartComponent {\\n  readonly instanceId = generateUniqueId(\'chart\');\\n  private readonly exportSvc = inject(ChartExportService);\\n\\n  readonly PAD_LEFT = 52;\\n  readonly PAD_TOP = 20;\\n  readonly PAD_RIGHT = 24;\\n  readonly PAD_BOTTOM = 36;\\n\\n  data = input.required<CandlestickItem[]>();\\n  height = input<number>(300);\\n  showGrid = input<boolean>(true);\\n  showLabels = input<boolean>(true);\\n  showExport = input<boolean>(false);\\n  colors = input<string[]>(CHART_COLORS);\\n  bullishColor = input<string>(\'#10b981\');\\n  bearishColor = input<string>(\'#ef4444\');\\n\\n  hoveredIndex = signal<number | null>(null);\\n  tooltip = signal<{\\n    x: number;\\n    y: number;\\n    date: string | Date;\\n    isBullish: boolean;\\n    orig: CandlestickItem;\\n    ha: { open: number; high: number; low: number; close: number };\\n  } | null>(null);\\n\\n  containerWidth = signal<number>(600);\\n  svgEl = viewChild<ElementRef<SVGElement>>(\'svgEl\');\\n  private container = viewChild<ElementRef>(\'container\');\\n\\n  constructor() {\\n    const hostEl = inject(ElementRef).nativeElement;\\n    if (typeof ResizeObserver !== \'undefined\') {\\n      const resizeObserver = new ResizeObserver(entries => {\\n        if (!entries || entries.length === 0) return;\\n        const width = entries[0].contentRect.width;\\n        if (width > 0) {\\n          // Subtract padding\\n          this.containerWidth.set(width - 32);\\n        }\\n      });\\n      resizeObserver.observe(hostEl);\\n      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());\\n    }\\n  }\\n\\n  innerW = computed(() => Math.max(200, this.containerWidth() - this.PAD_LEFT - this.PAD_RIGHT));\\n  innerH = computed(() => Math.max(100, this.height() - this.PAD_TOP - this.PAD_BOTTOM));\\n\\n  // Compute Heikin-Ashi series\\n  heikinAshiData = computed<HeikinAshiCalculatedItem[]>(() => {\\n    const raw = this.data();\\n    if (raw.length === 0) return [];\\n    const ha: HeikinAshiCalculatedItem[] = [];\\n\\n    // First item\\n    const item0 = raw[0];\\n    const haClose0 = (item0.open + item0.high + item0.low + item0.close) / 4;\\n    const haOpen0 = (item0.open + item0.close) / 2;\\n    const haHigh0 = Math.max(item0.high, haOpen0, haClose0);\\n    const haLow0 = Math.min(item0.low, haOpen0, haClose0);\\n\\n    ha.push({\\n      date: item0.date,\\n      open: haOpen0,\\n      high: haHigh0,\\n      low: haLow0,\\n      close: haClose0,\\n      original: item0\\n    });\\n\\n    // Subsequent items\\n    for (let i = 1; i < raw.length; i++) {\\n      const item = raw[i];\\n      const prev = ha[i - 1];\\n\\n      const haClose = (item.open + item.high + item.low + item.close) / 4;\\n      const haOpen = (prev.open + prev.close) / 2;\\n      const haHigh = Math.max(item.high, haOpen, haClose);\\n      const haLow = Math.min(item.low, haOpen, haClose);\\n\\n      ha.push({\\n        date: item.date,\\n        open: haOpen,\\n        high: haHigh,\\n        low: haLow,\\n        close: haClose,\\n        original: item\\n      });\\n    }\\n\\n    return ha;\\n  });\\n\\n  yMin = computed(() => {\\n    const items = this.heikinAshiData();\\n    if (items.length === 0) return 0;\\n    const lows = items.map(d => d.low);\\n    const minVal = Math.min(...lows);\\n    return minVal * 0.99; // 1% safety margin\\n  });\\n\\n  yMax = computed(() => {\\n    const items = this.heikinAshiData();\\n    if (items.length === 0) return 100;\\n    const highs = items.map(d => d.high);\\n    const maxVal = Math.max(...highs);\\n    return maxVal * 1.01; // 1% safety margin\\n  });\\n\\n  yTicks = computed(() => niceTicks(this.yMin(), this.yMax(), 5));\\n\\n  xPos(index: number): number {\\n    const count = this.heikinAshiData().length || 1;\\n    const step = this.innerW() / count;\\n    return index * step + step * 0.15; // padding\\n  }\\n\\n  yPos(y: number): number {\\n    return scale(y, this.yMin(), this.yMax(), this.innerH(), 0);\\n  }\\n\\n  candleWidth(): number {\\n    const count = this.heikinAshiData().length || 1;\\n    return (this.innerW() / count) * 0.7; // 70% width\\n  }\\n\\n  computedCandles = computed(() => {\\n    const items = this.heikinAshiData();\\n    const count = items.length;\\n    if (count === 0) return [];\\n    const width = this.candleWidth();\\n\\n    return items.map((item, idx) => {\\n      const x = this.xPos(idx);\\n      const centerX = x + width / 2;\\n\\n      const yOpen = this.yPos(item.open);\\n      const yClose = this.yPos(item.close);\\n      const yHigh = this.yPos(item.high);\\n      const yLow = this.yPos(item.low);\\n\\n      const y = Math.min(yOpen, yClose);\\n      const rectH = Math.max(2, Math.abs(yOpen - yClose));\\n\\n      const isBullish = item.close >= item.open;\\n      const color = isBullish ? this.bullishColor() : this.bearishColor();\\n\\n      return {\\n        x,\\n        centerX,\\n        width,\\n        yHigh,\\n        yLow,\\n        yOpen,\\n        yClose,\\n        y,\\n        rectH,\\n        color,\\n        isBullish,\\n        raw: item\\n      };\\n    });\\n  });\\n\\n  shouldShowXLabel(index: number): boolean {\\n    const count = this.heikinAshiData().length;\\n    if (count <= 10) return true;\\n    if (count <= 25) return index % 2 === 0;\\n    if (count <= 50) return index % 5 === 0;\\n    return index % 10 === 0;\\n  }\\n\\n  onCandleHover(event: MouseEvent, item: HeikinAshiCalculatedItem, index: number) {\\n    this.hoveredIndex.set(index);\\n    const containerEl = this.container()?.nativeElement;\\n    if (!containerEl) return;\\n    const rect = containerEl.getBoundingClientRect();\\n    const tooltipX = event.clientX - rect.left;\\n    const tooltipY = event.clientY - rect.top;\\n\\n    this.tooltip.set({\\n      x: tooltipX,\\n      y: tooltipY,\\n      date: item.date,\\n      isBullish: item.close >= item.open,\\n      orig: item.original,\\n      ha: { open: item.open, high: item.high, low: item.low, close: item.close }\\n    });\\n  }\\n\\n  formatDate(d: string | Date): string {\\n    if (d instanceof Date) {\\n      return d.toLocaleDateString(undefined, { month: \'short\', day: \'numeric\' });\\n    }\\n    return String(d);\\n  }\\n\\n  onExport(type: ExportFormat): void {\\n    if (type === \'json\') this.exportToJson();\\n    else if (type === \'csv\') this.exportToCsv();\\n    else if (type === \'svg\') this.exportToSvg();\\n    else if (type === \'pdf\') this.exportToPdf();\\n  }\\n\\n  exportToCsv(): void {\\n    const items = this.heikinAshiData();\\n    if (!items.length) return;\\n    const headers = [\'Date\', \'Orig_Open\', \'Orig_High\', \'Orig_Low\', \'Orig_Close\', \'HA_Open\', \'HA_High\', \'HA_Low\', \'HA_Close\'];\\n    const rows = items.map(item => [\\n      this.formatDate(item.date),\\n      item.original.open, item.original.high, item.original.low, item.original.close,\\n      item.open, item.high, item.low, item.close\\n    ]);\\n    this.exportSvc.downloadCsv(headers, rows, \'heikin-ashi-data.csv\');\\n  }\\n\\n  exportToJson(): void {\\n    const items = this.heikinAshiData();\\n    if (!items.length) return;\\n    this.exportSvc.downloadJson(items, \'heikin-ashi-data.json\');\\n  }\\n\\n  exportToSvg(): void {\\n    this.exportSvc.downloadSvg(this.svgEl()?.nativeElement, \'heikin-ashi-chart.svg\');\\n  }\\n\\n  exportToPdf(): void {\\n    this.exportSvc.downloadPdf(this.svgEl()?.nativeElement, \'Heikin-Ashi Chart\', \'heikin-ashi-chart.pdf\');\\n  }\\n\\n  readonly fmtNum = fmtNum;\\n}\\n","assetsDirs":[],"styleUrlsData":"","stylesData":"\\n    :host {\\n      display: block;\\n      width: 100%;\\n    }\\n    .ngx-heikin-ashi-chart {\\n      position: relative;\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n    }\\n    .chart-svg-container {\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .axis-label {\\n      font-size: 10px;\\n      fill: #64748b;\\n      font-weight: 500;\\n    }\\n\\n    @keyframes candleGrow {\\n      from { transform: scaleY(0); opacity: 0; }\\n      to { transform: scaleY(1); opacity: 1; }\\n    }\\n\\n    .candle-rect {\\n      cursor: pointer;\\n      transition: fill 0.15s, opacity 0.15s, stroke-width 0.15s, filter 0.15s;\\n      animation: candleGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;\\n    }\\n    .candle-rect.hovered {\\n      filter: brightness(1.05) drop-shadow(0 4px 10px rgba(0,0,0,0.18));\\n      stroke-width: 1.5px;\\n    }\\n    .crosshair-line {\\n      pointer-events: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.94));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 11px;\\n      z-index: 100;\\n      min-width: 210px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      transition: left 0.08s ease-out, top 0.08s ease-out;\\n    }\\n    .tooltip-header {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tooltip-direction {\\n      font-size: 10px;\\n      font-weight: 700;\\n      margin-bottom: 8px;\\n      text-transform: uppercase;\\n      letter-spacing: 0.3px;\\n    }\\n    .tooltip-columns {\\n      display: flex;\\n      gap: 12px;\\n    }\\n    .tooltip-col {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 2px;\\n      flex: 1;\\n    }\\n    .tooltip-col.bordered {\\n      border-left: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-left: 12px;\\n    }\\n    .col-title {\\n      font-weight: 600;\\n      font-size: 9.5px;\\n      color: rgba(255, 255, 255, 0.5);\\n      text-transform: uppercase;\\n      margin-bottom: 4px;\\n    }\\n    .tooltip-val {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: 8px;\\n      color: rgba(248, 250, 252, 0.85);\\n    }\\n    .tooltip-val span {\\n      color: rgba(255, 255, 255, 0.55);\\n    }\\n    .tooltip-val strong {\\n      color: #f8fafc;\\n      font-family: monospace;\\n      font-weight: 700;\\n    }\\n\\n    /* Export styles removed */\\n    .chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }\\n  \\n","constructorObj":{"name":"constructor","description":"","deprecated":false,"deprecationMessage":"","args":[],"line":344},"extends":[]},{"name":"HistogramComponent","id":"component-HistogramComponent-a1fc715d8a5488866193b91893083a529ee2a7a787fb03a1a4e555159fd9431d4b9c7015f404b81dafeb42ad74e3066938b8be745818de654b0a6d4a9299f10e","file":"projects/ngx-core-components/charts/histogram/histogram.component.ts","changeDetection":"ChangeDetectionStrategy.OnPush","encapsulation":[],"entryComponents":[],"inputs":[],"outputs":[],"providers":[],"selector":"ngx-histogram","styleUrls":[],"styles":["\\n    :host {\\n      display: block;\\n      position: relative;\\n    }\\n    .ngx-histogram {\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-header {\\n      display: flex;\\n      justify-content: space-between;\\n      align-items: center;\\n      margin-bottom: 12px;\\n      min-height: 24px;\\n      position: relative;\\n    }\\n    .header-info {\\n      display: flex;\\n      flex-direction: column;\\n    }\\n    .header-title {\\n      font-size: 14px;\\n      font-weight: 700;\\n      color: var(--ngx-chart-axis-text, #334155);\\n    }\\n    .header-subtitle {\\n      font-size: 11px;\\n      font-weight: 500;\\n      color: var(--ngx-chart-axis-text, #64748b);\\n    }\\n    .histogram-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .grid-line {\\n      stroke: var(--ngx-chart-grid, #f1f5f9);\\n      stroke-width: 1;\\n      stroke-dasharray: 3,3;\\n    }\\n    .axis-line {\\n      stroke: var(--ngx-chart-axis, #cbd5e1);\\n      stroke-width: 1.5;\\n    }\\n    .tick-line {\\n      stroke: var(--ngx-chart-axis, #cbd5e1);\\n      stroke-width: 1.5;\\n    }\\n    .tick-label {\\n      font-size: 10px;\\n      fill: var(--ngx-chart-axis-text, #64748b);\\n      font-weight: 550;\\n      user-select: none;\\n    }\\n    .x-tick-label {\\n      font-size: 9px;\\n    }\\n    .histogram-bar {\\n      cursor: pointer;\\n      transition: all 0.2s ease-in-out;\\n      transform-origin: bottom;\\n      animation: barGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;\\n      opacity: 0;\\n    }\\n    @keyframes barGrow {\\n      from { transform: scaleY(0); opacity: 0; }\\n      to { transform: scaleY(1); opacity: 1; }\\n    }\\n    .histogram-bar.dimmed {\\n      opacity: 0.3 !important;\\n    }\\n    .histogram-bar.highlighted {\\n      filter: drop-shadow(0 4px 8px rgba(0,0,0,0.15));\\n      stroke: #334155 !important;\\n      stroke-width: 1.5px !important;\\n    }\\n    .bar-label {\\n      font-size: 10px;\\n      font-weight: 600;\\n      fill: var(--ngx-chart-axis-text, #475569);\\n      user-select: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 12px;\\n      min-width: 150px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      z-index: 100;\\n      transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);\\n    }\\n    .tt-cat {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tt-row {\\n      display: flex;\\n      align-items: center;\\n      gap: 8px;\\n      margin-top: 4px;\\n    }\\n    .tt-name {\\n      color: rgba(248, 250, 252, 0.8);\\n      flex: 1;\\n    }\\n    .tt-val {\\n      font-weight: 700;\\n      font-family: monospace;\\n    }\\n\\n    /* Export dropdown styles removed */\\n  "],"template":"<div class=\\"ngx-histogram\\" (mouseleave)=\\"onMouseLeave()\\">\\n  <div class=\\"chart-header\\" (mousemove)=\\"$event.stopPropagation()\\" (mouseleave)=\\"onMouseLeave()\\">\\n    <div class=\\"header-info\\">\\n      <span class=\\"header-title\\">Histogram Distribution</span>\\n      <span class=\\"header-subtitle\\">Bins: {{ binsCount() }}</span>\\n    </div>\\n\\n    @if (showExport()) {\\n      <ngx-chart-export-menu (exportClicked)=\\"onExport($event)\\" />\\n    }\\n  </div>\\n\\n  <svg\\n    #svgEl\\n    class=\\"histogram-svg\\"\\n    [attr.width]=\\"\'100%\'\\"\\n    [attr.height]=\\"svgHeight()\\"\\n  >\\n    <g [attr.transform]=\\"\'translate(\' + margin().left + \',\' + margin().top + \')\'\\">\\n\\n      \x3c!-- Grid Lines --\x3e\\n      @if (showGrid()) {\\n        @for (tick of yTicks(); track tick) {\\n          <line\\n            [attr.x1]=\\"0\\"\\n            [attr.x2]=\\"innerW()\\"\\n            [attr.y1]=\\"yPos(tick)\\"\\n            [attr.y2]=\\"yPos(tick)\\"\\n            class=\\"grid-line\\"\\n          />\\n        }\\n      }\\n\\n      \x3c!-- Bars --\x3e\\n      @for (bin of computedBins(); track bin.index; let i = $index) {\\n        <rect\\n          [attr.x]=\\"bin.x\\"\\n          [attr.y]=\\"bin.y\\"\\n          [attr.width]=\\"bin.w\\"\\n          [attr.height]=\\"bin.h\\"\\n          [attr.fill]=\\"barColor(i)\\"\\n          class=\\"histogram-bar\\"\\n          [class.dimmed]=\\"hoveredIndex() !== null && hoveredIndex() !== i\\"\\n          [class.highlighted]=\\"hoveredIndex() === i\\"\\n          (mouseenter)=\\"onBarHover(i)\\"\\n          (mousemove)=\\"onMouseMove($event)\\"\\n          stroke=\\"#ffffff\\"\\n          stroke-width=\\"1\\"\\n          rx=\\"4\\"\\n          ry=\\"4\\"\\n          [style.animation-delay]=\\"(i * 0.03) + \'s\'\\"\\n        />\\n\\n        @if (showLabels() && bin.count > 0) {\\n          <text\\n            [attr.x]=\\"bin.x + bin.w / 2\\"\\n            [attr.y]=\\"bin.y - 6\\"\\n            text-anchor=\\"middle\\"\\n            class=\\"bar-label\\"\\n          >\\n            {{ bin.count }}\\n          </text>\\n        }\\n      }\\n\\n      \x3c!-- Y Axis --\x3e\\n      <g class=\\"y-axis\\">\\n        <line [attr.x1]=\\"0\\" [attr.x2]=\\"0\\" [attr.y1]=\\"0\\" [attr.y2]=\\"innerH()\\" class=\\"axis-line\\" />\\n        @for (tick of yTicks(); track tick) {\\n          <g [attr.transform]=\\"\'translate(0,\' + yPos(tick) + \')\'\\">\\n            <line [attr.x1]=\\"-4\\" [attr.x2]=\\"0\\" [attr.y1]=\\"0\\" [attr.y2]=\\"0\\" class=\\"tick-line\\" />\\n            <text\\n              [attr.x]=\\"-8\\"\\n              text-anchor=\\"end\\"\\n              dominant-baseline=\\"middle\\"\\n              class=\\"tick-label\\"\\n            >\\n              {{ labelFormatter() ? labelFormatter()!(tick) : formatNumber(tick) }}\\n            </text>\\n          </g>\\n        }\\n      </g>\\n\\n      \x3c!-- X Axis --\x3e\\n      <g [attr.transform]=\\"\'translate(0,\' + innerH() + \')\'\\" class=\\"x-axis\\">\\n        <line [attr.x1]=\\"0\\" [attr.x2]=\\"innerW()\\" [attr.y1]=\\"0\\" [attr.y2]=\\"0\\" class=\\"axis-line\\" />\\n        @for (bin of computedBins(); track bin.index) {\\n          <g [attr.transform]=\\"\'translate(\' + (bin.x + bin.w / 2) + \',0)\'\\">\\n            <line [attr.y1]=\\"0\\" [attr.y2]=\\"4\\" class=\\"tick-line\\" />\\n            <text\\n              [attr.y]=\\"16\\"\\n              text-anchor=\\"middle\\"\\n              class=\\"tick-label x-tick-label\\"\\n            >\\n              {{ bin.min | number:\'1.0-1\' }}\\n            </text>\\n          </g>\\n        }\\n        \x3c!-- Max tick label for X Axis end edge --\x3e\\n        @if (computedBins().length > 0) {\\n          @let lastBin = computedBins()[computedBins().length - 1];\\n          <g [attr.transform]=\\"\'translate(\' + (lastBin.x + lastBin.w) + \',0)\'\\">\\n            <line [attr.y1]=\\"0\\" [attr.y2]=\\"4\\" class=\\"tick-line\\" />\\n            <text\\n              [attr.y]=\\"16\\"\\n              text-anchor=\\"middle\\"\\n              class=\\"tick-label x-tick-label\\"\\n            >\\n              {{ lastBin.max | number:\'1.0-1\' }}\\n            </text>\\n          </g>\\n        }\\n      </g>\\n    </g>\\n  </svg>\\n\\n  \x3c!-- Glassmorphic Tooltip --\x3e\\n  @if (tooltip(); as t) {\\n    <div class=\\"chart-tooltip\\" [style.left.px]=\\"tooltipX()\\" [style.top.px]=\\"tooltipY()\\">\\n      @if (tooltipTemplate()) {\\n        <ng-container\\n          *ngTemplateOutlet=\\"tooltipTemplate()!; context: { $implicit: t }\\"\\n        ></ng-container>\\n      } @else {\\n        <div class=\\"tt-cat\\">Range: {{ t.label }}</div>\\n        <div class=\\"tt-row\\">\\n          <span class=\\"tt-name\\">Frequency</span>\\n          <span class=\\"tt-val\\">{{ t.count }}</span>\\n        </div>\\n        <div class=\\"tt-row\\">\\n          <span class=\\"tt-name\\">Percentage</span>\\n          <span class=\\"tt-val\\">{{ t.percentage | number:\'1.0-1\' }}%</span>\\n        </div>\\n      }\\n    </div>\\n  }\\n</div>\\n","templateUrl":[],"viewProviders":[],"hostDirectives":[],"inputsClass":[{"name":"binsCount","defaultValue":"10","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":304,"required":false},{"name":"colors","defaultValue":"CHART_COLORS","deprecated":false,"deprecationMessage":"","type":"string[]","indexKey":"","optional":false,"description":"","line":308,"required":false},{"name":"data","defaultValue":"[]","deprecated":false,"deprecationMessage":"","type":"number[]","indexKey":"","optional":false,"description":"","line":303,"required":false},{"name":"height","defaultValue":"300","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":305,"required":false},{"name":"showExport","defaultValue":"false","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":309,"required":false},{"name":"showGrid","defaultValue":"true","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":306,"required":false},{"name":"showLabels","defaultValue":"true","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":307,"required":false},{"name":"tooltipTemplate","defaultValue":"null","deprecated":false,"deprecationMessage":"","type":"TemplateRef<any> | null","indexKey":"","optional":false,"description":"","line":311,"required":false}],"outputsClass":[],"propertiesClass":[{"name":"computedBins","defaultValue":"computed<HistogramBin[]>(() => {\\n    const rawData = this.data();\\n    const count = Math.max(1, this.binsCount() || 10);\\n    if (rawData.length === 0) return [];\\n\\n    let min = Math.min(...rawData);\\n    let max = Math.max(...rawData);\\n    if (min === max) {\\n      min -= 1;\\n      max += 1;\\n    }\\n\\n    const range = max - min;\\n    const binWidth = range / count;\\n\\n    // Initialize bins\\n    const bins = Array.from({ length: count }, (_, i) => {\\n      const bMin = min + i * binWidth;\\n      const bMax = bMin + binWidth;\\n      return {\\n        index: i,\\n        min: bMin,\\n        max: bMax,\\n        count: 0,\\n        label: `${bMin.toFixed(1)} – ${bMax.toFixed(1)}`\\n      };\\n    });\\n\\n    // Populate bins\\n    rawData.forEach(val => {\\n      let bIdx = Math.floor((val - min) / binWidth);\\n      if (bIdx >= count) bIdx = count - 1;\\n      if (bIdx < 0) bIdx = 0;\\n      bins[bIdx].count++;\\n    });\\n\\n    const maxCount = Math.max(1, ...bins.map(b => b.count));\\n    const w = this.innerW();\\n    const h = this.innerH();\\n    const barW = w / count;\\n\\n    return bins.map((b, i) => {\\n      const barH = scale(b.count, 0, maxCount, 0, h);\\n      return {\\n        ...b,\\n        x: i * barW,\\n        y: h - barH,\\n        w: barW * 0.95, // 5% spacing between bars\\n        h: Math.max(2, barH)\\n      } as HistogramBin;\\n    });\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":347},{"name":"containerWidth","defaultValue":"signal<number>(500)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":313},{"name":"exportSvc","defaultValue":"inject(ChartExportService)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":301,"modifierKind":[123,148]},{"name":"hoveredIndex","defaultValue":"signal<number | null>(null)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":314},{"name":"innerH","defaultValue":"computed(() => Math.max(10, this.svgHeight() - this.margin().top - this.margin().bottom))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":330},{"name":"innerW","defaultValue":"computed(() => Math.max(10, this.containerWidth() - this.margin().left - this.margin().right))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":329},{"name":"labelFormatter","defaultValue":"input<((v: number) => string) | undefined>(undefined)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":310},{"name":"margin","defaultValue":"computed(() => ({\\n    top: 30,\\n    right: 25,\\n    bottom: 30,\\n    left: 45\\n  }))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":321},{"name":"svgEl","defaultValue":"viewChild<ElementRef<SVGElement>>(\'svgEl\')","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":319},{"name":"svgHeight","defaultValue":"computed(() => this.height())","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":328},{"name":"tooltip","defaultValue":"signal<any | null>(null)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":315},{"name":"tooltipX","defaultValue":"signal<number>(0)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":316},{"name":"tooltipY","defaultValue":"signal<number>(0)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":317},{"name":"yDomainMax","defaultValue":"computed(() => {\\n    const ticks = this.yTicks();\\n    return ticks[ticks.length - 1] || 10;\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":407},{"name":"yTicks","defaultValue":"computed(() => {\\n    const bins = this.computedBins();\\n    if (bins.length === 0) return [0, 5, 10];\\n    const maxCount = Math.max(1, ...bins.map(b => b.count));\\n    return niceTicks(0, maxCount, 5);\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":400}],"methodsClass":[{"name":"barColor","args":[{"name":"i","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"string","typeParameters":[],"line":416,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"i","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"exportToCsv","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":455,"deprecated":false,"deprecationMessage":""},{"name":"exportToJson","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":463,"deprecated":false,"deprecationMessage":""},{"name":"exportToPdf","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":479,"deprecated":false,"deprecationMessage":""},{"name":"exportToSvg","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":475,"deprecated":false,"deprecationMessage":""},{"name":"formatNumber","args":[{"name":"v","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"string","typeParameters":[],"line":483,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"v","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onBarHover","args":[{"name":"idx","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":421,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"idx","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onExport","args":[{"name":"type","type":"ExportFormat","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":448,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"type","type":"ExportFormat","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onMouseLeave","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":443,"deprecated":false,"deprecationMessage":""},{"name":"onMouseMove","args":[{"name":"event","type":"MouseEvent","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":433,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"event","type":"MouseEvent","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"yPos","args":[{"name":"val","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"number","typeParameters":[],"line":412,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"val","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]}],"deprecated":false,"deprecationMessage":"","hostBindings":[],"hostListeners":[],"standalone":true,"imports":[{"name":"ChartExportMenuComponent","type":"component"},{"name":"DecimalPipe","type":"pipe"},{"name":"NgTemplateOutlet"}],"description":"","rawdescription":"\\n","type":"component","sourceCode":"import {\\n  Component, ChangeDetectionStrategy, input, computed, signal,\\n  ElementRef, inject, DestroyRef, TemplateRef, viewChild\\n} from \'@angular/core\';\\nimport { DecimalPipe, NgTemplateOutlet } from \'@angular/common\';\\nimport { ChartExportService } from \'../shared/chart-export.service\';\\nimport { ChartExportMenuComponent } from \'../shared/chart-export-menu.component\';\\nimport type { ExportFormat } from \'../shared/chart-export-menu.component\';\\nimport { CHART_COLORS, fmtNum, niceTicks, scale } from \'../shared/chart-utils\';\\n\\nexport interface HistogramBin {\\n  index: number;\\n  min: number;\\n  max: number;\\n  count: number;\\n  label: string;\\n  x: number;\\n  y: number;\\n  w: number;\\n  h: number;\\n}\\n\\n@Component({\\n  selector: \'ngx-histogram\',\\n  standalone: true,\\n  imports: [ChartExportMenuComponent, DecimalPipe, NgTemplateOutlet],\\n  changeDetection: ChangeDetectionStrategy.OnPush,\\n  template: `\\n    <div class=\\"ngx-histogram\\" (mouseleave)=\\"onMouseLeave()\\">\\n      <div class=\\"chart-header\\" (mousemove)=\\"$event.stopPropagation()\\" (mouseleave)=\\"onMouseLeave()\\">\\n        <div class=\\"header-info\\">\\n          <span class=\\"header-title\\">Histogram Distribution</span>\\n          <span class=\\"header-subtitle\\">Bins: {{ binsCount() }}</span>\\n        </div>\\n        \\n        @if (showExport()) {\\n          <ngx-chart-export-menu (exportClicked)=\\"onExport($event)\\" />\\n        }\\n      </div>\\n\\n      <svg\\n        #svgEl\\n        class=\\"histogram-svg\\"\\n        [attr.width]=\\"\'100%\'\\"\\n        [attr.height]=\\"svgHeight()\\"\\n      >\\n        <g [attr.transform]=\\"\'translate(\' + margin().left + \',\' + margin().top + \')\'\\">\\n          \\n          \x3c!-- Grid Lines --\x3e\\n          @if (showGrid()) {\\n            @for (tick of yTicks(); track tick) {\\n              <line\\n                [attr.x1]=\\"0\\"\\n                [attr.x2]=\\"innerW()\\"\\n                [attr.y1]=\\"yPos(tick)\\"\\n                [attr.y2]=\\"yPos(tick)\\"\\n                class=\\"grid-line\\"\\n              />\\n            }\\n          }\\n\\n          \x3c!-- Bars --\x3e\\n          @for (bin of computedBins(); track bin.index; let i = $index) {\\n            <rect\\n              [attr.x]=\\"bin.x\\"\\n              [attr.y]=\\"bin.y\\"\\n              [attr.width]=\\"bin.w\\"\\n              [attr.height]=\\"bin.h\\"\\n              [attr.fill]=\\"barColor(i)\\"\\n              class=\\"histogram-bar\\"\\n              [class.dimmed]=\\"hoveredIndex() !== null && hoveredIndex() !== i\\"\\n              [class.highlighted]=\\"hoveredIndex() === i\\"\\n              (mouseenter)=\\"onBarHover(i)\\"\\n              (mousemove)=\\"onMouseMove($event)\\"\\n              stroke=\\"#ffffff\\"\\n              stroke-width=\\"1\\"\\n              rx=\\"4\\"\\n              ry=\\"4\\"\\n              [style.animation-delay]=\\"(i * 0.03) + \'s\'\\"\\n            />\\n            \\n            @if (showLabels() && bin.count > 0) {\\n              <text\\n                [attr.x]=\\"bin.x + bin.w / 2\\"\\n                [attr.y]=\\"bin.y - 6\\"\\n                text-anchor=\\"middle\\"\\n                class=\\"bar-label\\"\\n              >\\n                {{ bin.count }}\\n              </text>\\n            }\\n          }\\n\\n          \x3c!-- Y Axis --\x3e\\n          <g class=\\"y-axis\\">\\n            <line [attr.x1]=\\"0\\" [attr.x2]=\\"0\\" [attr.y1]=\\"0\\" [attr.y2]=\\"innerH()\\" class=\\"axis-line\\" />\\n            @for (tick of yTicks(); track tick) {\\n              <g [attr.transform]=\\"\'translate(0,\' + yPos(tick) + \')\'\\">\\n                <line [attr.x1]=\\"-4\\" [attr.x2]=\\"0\\" [attr.y1]=\\"0\\" [attr.y2]=\\"0\\" class=\\"tick-line\\" />\\n                <text\\n                  [attr.x]=\\"-8\\"\\n                  text-anchor=\\"end\\"\\n                  dominant-baseline=\\"middle\\"\\n                  class=\\"tick-label\\"\\n                >\\n                  {{ labelFormatter() ? labelFormatter()!(tick) : formatNumber(tick) }}\\n                </text>\\n              </g>\\n            }\\n          </g>\\n\\n          \x3c!-- X Axis --\x3e\\n          <g [attr.transform]=\\"\'translate(0,\' + innerH() + \')\'\\" class=\\"x-axis\\">\\n            <line [attr.x1]=\\"0\\" [attr.x2]=\\"innerW()\\" [attr.y1]=\\"0\\" [attr.y2]=\\"0\\" class=\\"axis-line\\" />\\n            @for (bin of computedBins(); track bin.index) {\\n              <g [attr.transform]=\\"\'translate(\' + (bin.x + bin.w / 2) + \',0)\'\\">\\n                <line [attr.y1]=\\"0\\" [attr.y2]=\\"4\\" class=\\"tick-line\\" />\\n                <text\\n                  [attr.y]=\\"16\\"\\n                  text-anchor=\\"middle\\"\\n                  class=\\"tick-label x-tick-label\\"\\n                >\\n                  {{ bin.min | number:\'1.0-1\' }}\\n                </text>\\n              </g>\\n            }\\n            \x3c!-- Max tick label for X Axis end edge --\x3e\\n            @if (computedBins().length > 0) {\\n              @let lastBin = computedBins()[computedBins().length - 1];\\n              <g [attr.transform]=\\"\'translate(\' + (lastBin.x + lastBin.w) + \',0)\'\\">\\n                <line [attr.y1]=\\"0\\" [attr.y2]=\\"4\\" class=\\"tick-line\\" />\\n                <text\\n                  [attr.y]=\\"16\\"\\n                  text-anchor=\\"middle\\"\\n                  class=\\"tick-label x-tick-label\\"\\n                >\\n                  {{ lastBin.max | number:\'1.0-1\' }}\\n                </text>\\n              </g>\\n            }\\n          </g>\\n        </g>\\n      </svg>\\n\\n      \x3c!-- Glassmorphic Tooltip --\x3e\\n      @if (tooltip(); as t) {\\n        <div class=\\"chart-tooltip\\" [style.left.px]=\\"tooltipX()\\" [style.top.px]=\\"tooltipY()\\">\\n          @if (tooltipTemplate()) {\\n            <ng-container\\n              *ngTemplateOutlet=\\"tooltipTemplate()!; context: { $implicit: t }\\"\\n            ></ng-container>\\n          } @else {\\n            <div class=\\"tt-cat\\">Range: {{ t.label }}</div>\\n            <div class=\\"tt-row\\">\\n              <span class=\\"tt-name\\">Frequency</span>\\n              <span class=\\"tt-val\\">{{ t.count }}</span>\\n            </div>\\n            <div class=\\"tt-row\\">\\n              <span class=\\"tt-name\\">Percentage</span>\\n              <span class=\\"tt-val\\">{{ t.percentage | number:\'1.0-1\' }}%</span>\\n            </div>\\n          }\\n        </div>\\n      }\\n    </div>\\n  `,\\n  styles: [`\\n    :host {\\n      display: block;\\n      position: relative;\\n    }\\n    .ngx-histogram {\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-header {\\n      display: flex;\\n      justify-content: space-between;\\n      align-items: center;\\n      margin-bottom: 12px;\\n      min-height: 24px;\\n      position: relative;\\n    }\\n    .header-info {\\n      display: flex;\\n      flex-direction: column;\\n    }\\n    .header-title {\\n      font-size: 14px;\\n      font-weight: 700;\\n      color: var(--ngx-chart-axis-text, #334155);\\n    }\\n    .header-subtitle {\\n      font-size: 11px;\\n      font-weight: 500;\\n      color: var(--ngx-chart-axis-text, #64748b);\\n    }\\n    .histogram-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .grid-line {\\n      stroke: var(--ngx-chart-grid, #f1f5f9);\\n      stroke-width: 1;\\n      stroke-dasharray: 3,3;\\n    }\\n    .axis-line {\\n      stroke: var(--ngx-chart-axis, #cbd5e1);\\n      stroke-width: 1.5;\\n    }\\n    .tick-line {\\n      stroke: var(--ngx-chart-axis, #cbd5e1);\\n      stroke-width: 1.5;\\n    }\\n    .tick-label {\\n      font-size: 10px;\\n      fill: var(--ngx-chart-axis-text, #64748b);\\n      font-weight: 550;\\n      user-select: none;\\n    }\\n    .x-tick-label {\\n      font-size: 9px;\\n    }\\n    .histogram-bar {\\n      cursor: pointer;\\n      transition: all 0.2s ease-in-out;\\n      transform-origin: bottom;\\n      animation: barGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;\\n      opacity: 0;\\n    }\\n    @keyframes barGrow {\\n      from { transform: scaleY(0); opacity: 0; }\\n      to { transform: scaleY(1); opacity: 1; }\\n    }\\n    .histogram-bar.dimmed {\\n      opacity: 0.3 !important;\\n    }\\n    .histogram-bar.highlighted {\\n      filter: drop-shadow(0 4px 8px rgba(0,0,0,0.15));\\n      stroke: #334155 !important;\\n      stroke-width: 1.5px !important;\\n    }\\n    .bar-label {\\n      font-size: 10px;\\n      font-weight: 600;\\n      fill: var(--ngx-chart-axis-text, #475569);\\n      user-select: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 12px;\\n      min-width: 150px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      z-index: 100;\\n      transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);\\n    }\\n    .tt-cat {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tt-row {\\n      display: flex;\\n      align-items: center;\\n      gap: 8px;\\n      margin-top: 4px;\\n    }\\n    .tt-name {\\n      color: rgba(248, 250, 252, 0.8);\\n      flex: 1;\\n    }\\n    .tt-val {\\n      font-weight: 700;\\n      font-family: monospace;\\n    }\\n\\n    /* Export dropdown styles removed */\\n  `]\\n})\\nexport class HistogramComponent {\\n  private readonly exportSvc = inject(ChartExportService);\\n\\n  data = input<number[]>([]);\\n  binsCount = input<number>(10);\\n  height = input<number>(300);\\n  showGrid = input<boolean>(true);\\n  showLabels = input<boolean>(true);\\n  colors = input<string[]>(CHART_COLORS);\\n  showExport = input<boolean>(false);\\n  labelFormatter = input<((v: number) => string) | undefined>(undefined);\\n  tooltipTemplate = input<TemplateRef<any> | null>(null);\\n\\n  containerWidth = signal<number>(500);\\n  hoveredIndex = signal<number | null>(null);\\n  tooltip = signal<any | null>(null);\\n  tooltipX = signal<number>(0);\\n  tooltipY = signal<number>(0);\\n\\n  svgEl = viewChild<ElementRef<SVGElement>>(\'svgEl\');\\n\\n  margin = computed(() => ({\\n    top: 30,\\n    right: 25,\\n    bottom: 30,\\n    left: 45\\n  }));\\n\\n  svgHeight = computed(() => this.height());\\n  innerW = computed(() => Math.max(10, this.containerWidth() - this.margin().left - this.margin().right));\\n  innerH = computed(() => Math.max(10, this.svgHeight() - this.margin().top - this.margin().bottom));\\n\\n  constructor() {\\n    const hostEl = inject(ElementRef).nativeElement;\\n    if (typeof ResizeObserver !== \'undefined\') {\\n      const resizeObserver = new ResizeObserver(entries => {\\n        if (!entries || entries.length === 0) return;\\n        const width = entries[0].contentRect.width;\\n        if (width > 0) {\\n          this.containerWidth.set(width);\\n        }\\n      });\\n      resizeObserver.observe(hostEl);\\n      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());\\n    }\\n  }\\n\\n  computedBins = computed<HistogramBin[]>(() => {\\n    const rawData = this.data();\\n    const count = Math.max(1, this.binsCount() || 10);\\n    if (rawData.length === 0) return [];\\n\\n    let min = Math.min(...rawData);\\n    let max = Math.max(...rawData);\\n    if (min === max) {\\n      min -= 1;\\n      max += 1;\\n    }\\n\\n    const range = max - min;\\n    const binWidth = range / count;\\n\\n    // Initialize bins\\n    const bins = Array.from({ length: count }, (_, i) => {\\n      const bMin = min + i * binWidth;\\n      const bMax = bMin + binWidth;\\n      return {\\n        index: i,\\n        min: bMin,\\n        max: bMax,\\n        count: 0,\\n        label: `${bMin.toFixed(1)} – ${bMax.toFixed(1)}`\\n      };\\n    });\\n\\n    // Populate bins\\n    rawData.forEach(val => {\\n      let bIdx = Math.floor((val - min) / binWidth);\\n      if (bIdx >= count) bIdx = count - 1;\\n      if (bIdx < 0) bIdx = 0;\\n      bins[bIdx].count++;\\n    });\\n\\n    const maxCount = Math.max(1, ...bins.map(b => b.count));\\n    const w = this.innerW();\\n    const h = this.innerH();\\n    const barW = w / count;\\n\\n    return bins.map((b, i) => {\\n      const barH = scale(b.count, 0, maxCount, 0, h);\\n      return {\\n        ...b,\\n        x: i * barW,\\n        y: h - barH,\\n        w: barW * 0.95, // 5% spacing between bars\\n        h: Math.max(2, barH)\\n      } as HistogramBin;\\n    });\\n  });\\n\\n  yTicks = computed(() => {\\n    const bins = this.computedBins();\\n    if (bins.length === 0) return [0, 5, 10];\\n    const maxCount = Math.max(1, ...bins.map(b => b.count));\\n    return niceTicks(0, maxCount, 5);\\n  });\\n\\n  yDomainMax = computed(() => {\\n    const ticks = this.yTicks();\\n    return ticks[ticks.length - 1] || 10;\\n  });\\n\\n  yPos(val: number): number {\\n    return scale(val, 0, this.yDomainMax(), this.innerH(), 0);\\n  }\\n\\n  barColor(i: number): string {\\n    const colorsList = this.colors();\\n    return colorsList[i % colorsList.length];\\n  }\\n\\n  onBarHover(idx: number) {\\n    this.hoveredIndex.set(idx);\\n    const bin = this.computedBins()[idx];\\n    if (bin) {\\n      const total = this.data().length || 1;\\n      this.tooltip.set({\\n        ...bin,\\n        percentage: (bin.count / total) * 100\\n      });\\n    }\\n  }\\n\\n  onMouseMove(event: MouseEvent) {\\n    const el = event.currentTarget as SVGElement;\\n    const container = el.closest(\'.ngx-histogram\');\\n    if (container) {\\n      const rect = container.getBoundingClientRect();\\n      this.tooltipX.set(event.clientX - rect.left);\\n      this.tooltipY.set(event.clientY - rect.top);\\n    }\\n  }\\n\\n  onMouseLeave() {\\n    this.hoveredIndex.set(null);\\n    this.tooltip.set(null);\\n  }\\n\\n  onExport(type: ExportFormat): void {\\n    if (type === \'json\') this.exportToJson();\\n    else if (type === \'csv\') this.exportToCsv();\\n    else if (type === \'svg\') this.exportToSvg();\\n    else if (type === \'pdf\') this.exportToPdf();\\n  }\\n\\n  exportToCsv(): void {\\n    const bins = this.computedBins();\\n    if (!bins.length) return;\\n    const headers = [\'Bin Index\', \'Range Min\', \'Range Max\', \'Frequency\'];\\n    const rows = bins.map(b => [b.index, b.min, b.max, b.count]);\\n    this.exportSvc.downloadCsv(headers, rows, \'histogram-data.csv\');\\n  }\\n\\n  exportToJson(): void {\\n    const bins = this.computedBins();\\n    if (!bins.length) return;\\n    const data = bins.map(b => ({\\n      index: b.index,\\n      min: b.min,\\n      max: b.max,\\n      frequency: b.count\\n    }));\\n    this.exportSvc.downloadJson(data, \'histogram-data.json\');\\n  }\\n\\n  exportToSvg(): void {\\n    this.exportSvc.downloadSvg(this.svgEl()?.nativeElement, \'histogram.svg\');\\n  }\\n\\n  exportToPdf(): void {\\n    this.exportSvc.downloadPdf(this.svgEl()?.nativeElement, \'Histogram Distribution Analysis\', \'histogram.pdf\');\\n  }\\n\\n  formatNumber(v: number): string {\\n    return fmtNum(v);\\n  }\\n}\\n","assetsDirs":[],"styleUrlsData":"","stylesData":"\\n    :host {\\n      display: block;\\n      position: relative;\\n    }\\n    .ngx-histogram {\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-header {\\n      display: flex;\\n      justify-content: space-between;\\n      align-items: center;\\n      margin-bottom: 12px;\\n      min-height: 24px;\\n      position: relative;\\n    }\\n    .header-info {\\n      display: flex;\\n      flex-direction: column;\\n    }\\n    .header-title {\\n      font-size: 14px;\\n      font-weight: 700;\\n      color: var(--ngx-chart-axis-text, #334155);\\n    }\\n    .header-subtitle {\\n      font-size: 11px;\\n      font-weight: 500;\\n      color: var(--ngx-chart-axis-text, #64748b);\\n    }\\n    .histogram-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .grid-line {\\n      stroke: var(--ngx-chart-grid, #f1f5f9);\\n      stroke-width: 1;\\n      stroke-dasharray: 3,3;\\n    }\\n    .axis-line {\\n      stroke: var(--ngx-chart-axis, #cbd5e1);\\n      stroke-width: 1.5;\\n    }\\n    .tick-line {\\n      stroke: var(--ngx-chart-axis, #cbd5e1);\\n      stroke-width: 1.5;\\n    }\\n    .tick-label {\\n      font-size: 10px;\\n      fill: var(--ngx-chart-axis-text, #64748b);\\n      font-weight: 550;\\n      user-select: none;\\n    }\\n    .x-tick-label {\\n      font-size: 9px;\\n    }\\n    .histogram-bar {\\n      cursor: pointer;\\n      transition: all 0.2s ease-in-out;\\n      transform-origin: bottom;\\n      animation: barGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;\\n      opacity: 0;\\n    }\\n    @keyframes barGrow {\\n      from { transform: scaleY(0); opacity: 0; }\\n      to { transform: scaleY(1); opacity: 1; }\\n    }\\n    .histogram-bar.dimmed {\\n      opacity: 0.3 !important;\\n    }\\n    .histogram-bar.highlighted {\\n      filter: drop-shadow(0 4px 8px rgba(0,0,0,0.15));\\n      stroke: #334155 !important;\\n      stroke-width: 1.5px !important;\\n    }\\n    .bar-label {\\n      font-size: 10px;\\n      font-weight: 600;\\n      fill: var(--ngx-chart-axis-text, #475569);\\n      user-select: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 12px;\\n      min-width: 150px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      z-index: 100;\\n      transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);\\n    }\\n    .tt-cat {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tt-row {\\n      display: flex;\\n      align-items: center;\\n      gap: 8px;\\n      margin-top: 4px;\\n    }\\n    .tt-name {\\n      color: rgba(248, 250, 252, 0.8);\\n      flex: 1;\\n    }\\n    .tt-val {\\n      font-weight: 700;\\n      font-family: monospace;\\n    }\\n\\n    /* Export dropdown styles removed */\\n  \\n","constructorObj":{"name":"constructor","description":"","deprecated":false,"deprecationMessage":"","args":[],"line":330},"extends":[]},{"name":"HLCChartComponent","id":"component-HLCChartComponent-67e1d8682b215d4957155aebf6698ff27d0f38a76993137eddf753e23dede2dd8d77013f4357485390269d0973b8624a31267713df2dd3153e32c75526ba34ca","file":"projects/ngx-core-components/charts/hlc-chart/hlc-chart.component.ts","changeDetection":"ChangeDetectionStrategy.OnPush","encapsulation":[],"entryComponents":[],"inputs":[],"outputs":[],"providers":[],"selector":"ngx-hlc-chart","styleUrls":[],"styles":["\\n    :host {\\n      display: block;\\n      width: 100%;\\n    }\\n    .ngx-hlc-chart {\\n      position: relative;\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n    }\\n    .chart-svg-container {\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .axis-label {\\n      font-size: 10px;\\n      fill: #64748b;\\n      font-weight: 500;\\n    }\\n    .hlc-line {\\n      transition: stroke-width 0.15s, stroke 0.15s;\\n    }\\n    .crosshair-line {\\n      pointer-events: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 11px;\\n      z-index: 100;\\n      min-width: 155px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      transition: left 0.08s ease-out, top 0.08s ease-out;\\n    }\\n    .tooltip-header {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tooltip-direction {\\n      font-size: 10px;\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      text-transform: uppercase;\\n      letter-spacing: 0.3px;\\n    }\\n    .tooltip-body {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 4px;\\n    }\\n    .tooltip-val {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: 16px;\\n      color: rgba(248, 250, 252, 0.85);\\n    }\\n    .tooltip-val strong {\\n      color: #f8fafc;\\n      font-family: monospace;\\n      font-weight: 700;\\n    }\\n\\n    /* Export styles removed */\\n    .chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }\\n  "],"template":"<div class=\\"ngx-hlc-chart\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n  \x3c!-- Toolbar with Export option --\x3e\\n  <div class=\\"chart-header\\" (mousemove)=\\"$event.stopPropagation()\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n    <div class=\\"chart-title-space\\"></div>\\n    @if (showExport()) {\\n      <ngx-chart-export-menu (exportClicked)=\\"onExport($event)\\" />\\n    }\\n  </div>\\n\\n  <div class=\\"chart-svg-container\\" #container>\\n    <svg\\n      #svgEl\\n      [attr.width]=\\"\'100%\'\\"\\n      [attr.height]=\\"height()\\"\\n      class=\\"chart-svg\\"\\n    >\\n      <g [attr.transform]=\\"\'translate(\' + PAD_LEFT + \',\' + PAD_TOP + \')\'\\">\\n        \x3c!-- Grid Lines (Horizontal) --\x3e\\n        @if (showGrid()) {\\n          @for (tick of yTicks(); track tick) {\\n            <line\\n              [attr.x1]=\\"0\\"\\n              [attr.x2]=\\"innerW()\\"\\n              [attr.y1]=\\"yPos(tick)\\"\\n              [attr.y2]=\\"yPos(tick)\\"\\n              stroke=\\"var(--ngx-chart-grid, #ebedf0)\\"\\n              stroke-dasharray=\\"3,3\\"\\n            />\\n          }\\n        }\\n\\n        \x3c!-- Y-Axis Labels --\x3e\\n        @if (showLabels()) {\\n          @for (tick of yTicks(); track tick) {\\n            <text\\n              x=\\"-10\\"\\n              [attr.y]=\\"yPos(tick) + 4\\"\\n              class=\\"axis-label y\\"\\n              text-anchor=\\"end\\"\\n            >{{ fmtNum(tick) }}</text>\\n          }\\n        }\\n\\n        \x3c!-- X-Axis Labels --\x3e\\n        @if (showLabels()) {\\n          @for (item of data(); track $index; let i = $index) {\\n            @if (shouldShowXLabel(i)) {\\n              <text\\n                [attr.x]=\\"xPos(i) + tickWidth() / 2\\"\\n                [attr.y]=\\"innerH() + 20\\"\\n                class=\\"axis-label x\\"\\n                text-anchor=\\"middle\\"\\n              >{{ formatDate(item.date) }}</text>\\n            }\\n          }\\n        }\\n\\n        \x3c!-- Active Crosshair --\x3e\\n        @if (hoveredIndex() !== null) {\\n          @if (computedTicks()[hoveredIndex()!]; as tick) {\\n            <line\\n              [attr.x1]=\\"0\\"\\n              [attr.x2]=\\"innerW()\\"\\n              [attr.y1]=\\"tick.yClose\\"\\n              [attr.y2]=\\"tick.yClose\\"\\n              stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n              stroke-width=\\"1.2\\"\\n              stroke-dasharray=\\"3,3\\"\\n              class=\\"crosshair-line\\"\\n            />\\n            <line\\n              [attr.x1]=\\"tick.centerX\\"\\n              [attr.x2]=\\"tick.centerX\\"\\n              [attr.y1]=\\"0\\"\\n              [attr.y2]=\\"innerH()\\"\\n              stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n              stroke-width=\\"1.2\\"\\n              stroke-dasharray=\\"3,3\\"\\n              class=\\"crosshair-line\\"\\n            />\\n          }\\n        }\\n\\n        \x3c!-- HLC Ticks --\x3e\\n        @for (tick of computedTicks(); track $index; let i = $index) {\\n          \x3c!-- Vertical Line (High to Low) --\x3e\\n          <line\\n            [attr.x1]=\\"tick.centerX\\"\\n            [attr.y1]=\\"tick.yHigh\\"\\n            [attr.x2]=\\"tick.centerX\\"\\n            [attr.y2]=\\"tick.yLow\\"\\n            [attr.stroke]=\\"tick.color\\"\\n            [attr.stroke-width]=\\"hoveredIndex() === i ? 3 : 2\\"\\n            class=\\"hlc-line\\"\\n          />\\n\\n          \x3c!-- Right Tick (Close) --\x3e\\n          <line\\n            [attr.x1]=\\"tick.centerX\\"\\n            [attr.y1]=\\"tick.yClose\\"\\n            [attr.x2]=\\"tick.centerX + tick.width / 2\\"\\n            [attr.y2]=\\"tick.yClose\\"\\n            [attr.stroke]=\\"tick.color\\"\\n            [attr.stroke-width]=\\"hoveredIndex() === i ? 3 : 2\\"\\n            class=\\"hlc-line\\"\\n          />\\n\\n          \x3c!-- Transparent Hover Area (UX optimization) --\x3e\\n          <rect\\n            [attr.x]=\\"tick.x\\"\\n            [attr.y]=\\"0\\"\\n            [attr.width]=\\"tick.cellWidth\\"\\n            [attr.height]=\\"innerH()\\"\\n            fill=\\"transparent\\"\\n            style=\\"cursor: pointer;\\"\\n            (mouseenter)=\\"onTickHover($event, tick.raw, i)\\"\\n            (mousemove)=\\"onTickHover($event, tick.raw, i)\\"\\n          />\\n        }\\n\\n        \x3c!-- Base axes borders --\x3e\\n        <line x1=\\"0\\" [attr.x2]=\\"innerW()\\" [attr.y1]=\\"innerH()\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n        <line x1=\\"0\\" x2=\\"0\\" y1=\\"0\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n      </g>\\n    </svg>\\n\\n    \x3c!-- Tooltip --\x3e\\n    @if (tooltip(); as t) {\\n      <div class=\\"chart-tooltip\\" [style.left.px]=\\"t.x\\" [style.top.px]=\\"t.y\\">\\n        <div class=\\"tooltip-header\\">{{ formatDate(t.date) }}</div>\\n        <div class=\\"tooltip-body\\">\\n          <div class=\\"tooltip-direction\\" [style.color]=\\"t.direction === \'Bullish\' ? \'#10b981\' : \'#ef4444\'\\">\\n            <strong>{{ t.direction }}</strong> ({{ t.changePct }})\\n          </div>\\n          <div class=\\"tooltip-val\\">\\n            <span>High:</span>\\n            <strong>{{ fmtNum(t.high) }}</strong>\\n          </div>\\n          <div class=\\"tooltip-val\\" style=\\"color: #38bdf8;\\">\\n            <span>Close:</span>\\n            <strong>{{ fmtNum(t.close) }}</strong>\\n          </div>\\n          <div class=\\"tooltip-val\\">\\n            <span>Low:</span>\\n            <strong>{{ fmtNum(t.low) }}</strong>\\n          </div>\\n        </div>\\n      </div>\\n    }\\n  </div>\\n</div>\\n","templateUrl":[],"viewProviders":[],"hostDirectives":[],"inputsClass":[{"name":"bearishColor","defaultValue":"\'#ef4444\'","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":278,"required":false},{"name":"bullishColor","defaultValue":"\'#10b981\'","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":277,"required":false},{"name":"colors","defaultValue":"CHART_COLORS","deprecated":false,"deprecationMessage":"","type":"string[]","indexKey":"","optional":false,"description":"","line":276,"required":false},{"name":"data","deprecated":false,"deprecationMessage":"","type":"HLCItem[]","indexKey":"","optional":false,"description":"","line":271,"required":true},{"name":"height","defaultValue":"300","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":272,"required":false},{"name":"showExport","defaultValue":"false","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":275,"required":false},{"name":"showGrid","defaultValue":"true","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":273,"required":false},{"name":"showLabels","defaultValue":"true","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":274,"required":false}],"outputsClass":[],"propertiesClass":[{"name":"computedTicks","defaultValue":"computed(() => {\\n    const items = this.data();\\n    const count = items.length;\\n    if (count === 0) return [];\\n    const width = this.tickWidth();\\n    const cellWidth = this.innerW() / count;\\n\\n    return items.map((item, idx) => {\\n      const x = this.xPos(idx);\\n      const centerX = x + cellWidth / 2;\\n\\n      const yHigh = this.yPos(item.high);\\n      const yLow = this.yPos(item.low);\\n      const yClose = this.yPos(item.close);\\n\\n      let isBullish = true;\\n      if (idx > 0) {\\n        isBullish = item.close >= items[idx - 1].close;\\n      }\\n      const color = isBullish ? this.bullishColor() : this.bearishColor();\\n\\n      return {\\n        x,\\n        centerX,\\n        cellWidth,\\n        width,\\n        yHigh,\\n        yLow,\\n        yClose,\\n        color,\\n        isBullish,\\n        raw: item\\n      };\\n    });\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":348},{"name":"container","defaultValue":"viewChild<ElementRef>(\'container\')","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":294,"modifierKind":[123]},{"name":"containerWidth","defaultValue":"signal<number>(600)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":292},{"name":"exportSvc","defaultValue":"inject(ChartExportService)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":264,"modifierKind":[123,148]},{"name":"fmtNum","defaultValue":"fmtNum","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":458,"modifierKind":[148]},{"name":"hoveredIndex","defaultValue":"signal<number | null>(null)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":280},{"name":"innerH","defaultValue":"computed(() => Math.max(100, this.height() - this.PAD_TOP - this.PAD_BOTTOM))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":313},{"name":"innerW","defaultValue":"computed(() => Math.max(200, this.containerWidth() - this.PAD_LEFT - this.PAD_RIGHT))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":312},{"name":"PAD_BOTTOM","defaultValue":"36","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":269,"modifierKind":[148]},{"name":"PAD_LEFT","defaultValue":"52","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":266,"modifierKind":[148]},{"name":"PAD_RIGHT","defaultValue":"24","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":268,"modifierKind":[148]},{"name":"PAD_TOP","defaultValue":"20","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":267,"modifierKind":[148]},{"name":"svgEl","defaultValue":"viewChild<ElementRef<SVGElement>>(\'svgEl\')","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":293},{"name":"tooltip","defaultValue":"signal<{\\n    x: number;\\n    y: number;\\n    date: string | Date;\\n    high: number;\\n    low: number;\\n    close: number;\\n    direction: \'Bullish\' | \'Bearish\';\\n    changePct: string;\\n  } | null>(null)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":281},{"name":"yMax","defaultValue":"computed(() => {\\n    const items = this.data();\\n    if (items.length === 0) return 100;\\n    const highs = items.map(d => d.high);\\n    const maxVal = Math.max(...highs);\\n    return maxVal * 1.01; // 1% safety margin\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":323},{"name":"yMin","defaultValue":"computed(() => {\\n    const items = this.data();\\n    if (items.length === 0) return 0;\\n    const lows = items.map(d => d.low);\\n    const minVal = Math.min(...lows);\\n    return minVal * 0.99; // 1% safety margin\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":315},{"name":"yTicks","defaultValue":"computed(() => niceTicks(this.yMin(), this.yMax(), 5))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":331}],"methodsClass":[{"name":"exportToCsv","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":436,"deprecated":false,"deprecationMessage":""},{"name":"exportToJson","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":444,"deprecated":false,"deprecationMessage":""},{"name":"exportToPdf","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":454,"deprecated":false,"deprecationMessage":""},{"name":"exportToSvg","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":450,"deprecated":false,"deprecationMessage":""},{"name":"formatDate","args":[{"name":"d","type":"string | Date","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"string","typeParameters":[],"line":422,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"d","type":"string | Date","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onExport","args":[{"name":"type","type":"ExportFormat","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":429,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"type","type":"ExportFormat","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onTickHover","args":[{"name":"event","type":"MouseEvent","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""},{"name":"item","type":"HLCItem","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""},{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":392,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"event","type":"MouseEvent","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}},{"name":"item","type":"HLCItem","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}},{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"shouldShowXLabel","args":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"boolean","typeParameters":[],"line":384,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"tickWidth","args":[],"optional":false,"returnType":"number","typeParameters":[],"line":343,"deprecated":false,"deprecationMessage":""},{"name":"xPos","args":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"number","typeParameters":[],"line":333,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"yPos","args":[{"name":"y","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"number","typeParameters":[],"line":339,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"y","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]}],"deprecated":false,"deprecationMessage":"","hostBindings":[],"hostListeners":[],"standalone":true,"imports":[{"name":"ChartExportMenuComponent","type":"component"}],"description":"","rawdescription":"\\n","type":"component","sourceCode":"import {\\n  Component, ChangeDetectionStrategy, input, computed, signal,\\n  ElementRef, inject, DestroyRef, viewChild\\n} from \'@angular/core\';\\nimport { ChartExportService } from \'../shared/chart-export.service\';\\nimport { ChartExportMenuComponent } from \'../shared/chart-export-menu.component\';\\nimport type { ExportFormat } from \'../shared/chart-export-menu.component\';\\nimport { niceTicks, scale, fmtNum, CHART_COLORS } from \'../shared/chart-utils\';\\n\\nexport interface HLCItem {\\n  date: string | Date;\\n  high: number;\\n  low: number;\\n  close: number;\\n}\\n\\n@Component({\\n  selector: \'ngx-hlc-chart\',\\n  standalone: true,\\n  imports: [ChartExportMenuComponent],\\n  changeDetection: ChangeDetectionStrategy.OnPush,\\n  template: `\\n    <div class=\\"ngx-hlc-chart\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n      \x3c!-- Toolbar with Export option --\x3e\\n      <div class=\\"chart-header\\" (mousemove)=\\"$event.stopPropagation()\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n        <div class=\\"chart-title-space\\"></div>\\n        @if (showExport()) {\\n          <ngx-chart-export-menu (exportClicked)=\\"onExport($event)\\" />\\n        }\\n      </div>\\n\\n      <div class=\\"chart-svg-container\\" #container>\\n        <svg\\n          #svgEl\\n          [attr.width]=\\"\'100%\'\\"\\n          [attr.height]=\\"height()\\"\\n          class=\\"chart-svg\\"\\n        >\\n          <g [attr.transform]=\\"\'translate(\' + PAD_LEFT + \',\' + PAD_TOP + \')\'\\">\\n            \x3c!-- Grid Lines (Horizontal) --\x3e\\n            @if (showGrid()) {\\n              @for (tick of yTicks(); track tick) {\\n                <line\\n                  [attr.x1]=\\"0\\"\\n                  [attr.x2]=\\"innerW()\\"\\n                  [attr.y1]=\\"yPos(tick)\\"\\n                  [attr.y2]=\\"yPos(tick)\\"\\n                  stroke=\\"var(--ngx-chart-grid, #ebedf0)\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                />\\n              }\\n            }\\n\\n            \x3c!-- Y-Axis Labels --\x3e\\n            @if (showLabels()) {\\n              @for (tick of yTicks(); track tick) {\\n                <text\\n                  x=\\"-10\\"\\n                  [attr.y]=\\"yPos(tick) + 4\\"\\n                  class=\\"axis-label y\\"\\n                  text-anchor=\\"end\\"\\n                >{{ fmtNum(tick) }}</text>\\n              }\\n            }\\n\\n            \x3c!-- X-Axis Labels --\x3e\\n            @if (showLabels()) {\\n              @for (item of data(); track $index; let i = $index) {\\n                @if (shouldShowXLabel(i)) {\\n                  <text\\n                    [attr.x]=\\"xPos(i) + tickWidth() / 2\\"\\n                    [attr.y]=\\"innerH() + 20\\"\\n                    class=\\"axis-label x\\"\\n                    text-anchor=\\"middle\\"\\n                  >{{ formatDate(item.date) }}</text>\\n                }\\n              }\\n            }\\n\\n            \x3c!-- Active Crosshair --\x3e\\n            @if (hoveredIndex() !== null) {\\n              @if (computedTicks()[hoveredIndex()!]; as tick) {\\n                <line\\n                  [attr.x1]=\\"0\\"\\n                  [attr.x2]=\\"innerW()\\"\\n                  [attr.y1]=\\"tick.yClose\\"\\n                  [attr.y2]=\\"tick.yClose\\"\\n                  stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n                  stroke-width=\\"1.2\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                  class=\\"crosshair-line\\"\\n                />\\n                <line\\n                  [attr.x1]=\\"tick.centerX\\"\\n                  [attr.x2]=\\"tick.centerX\\"\\n                  [attr.y1]=\\"0\\"\\n                  [attr.y2]=\\"innerH()\\"\\n                  stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n                  stroke-width=\\"1.2\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                  class=\\"crosshair-line\\"\\n                />\\n              }\\n            }\\n\\n            \x3c!-- HLC Ticks --\x3e\\n            @for (tick of computedTicks(); track $index; let i = $index) {\\n              \x3c!-- Vertical Line (High to Low) --\x3e\\n              <line\\n                [attr.x1]=\\"tick.centerX\\"\\n                [attr.y1]=\\"tick.yHigh\\"\\n                [attr.x2]=\\"tick.centerX\\"\\n                [attr.y2]=\\"tick.yLow\\"\\n                [attr.stroke]=\\"tick.color\\"\\n                [attr.stroke-width]=\\"hoveredIndex() === i ? 3 : 2\\"\\n                class=\\"hlc-line\\"\\n              />\\n\\n              \x3c!-- Right Tick (Close) --\x3e\\n              <line\\n                [attr.x1]=\\"tick.centerX\\"\\n                [attr.y1]=\\"tick.yClose\\"\\n                [attr.x2]=\\"tick.centerX + tick.width / 2\\"\\n                [attr.y2]=\\"tick.yClose\\"\\n                [attr.stroke]=\\"tick.color\\"\\n                [attr.stroke-width]=\\"hoveredIndex() === i ? 3 : 2\\"\\n                class=\\"hlc-line\\"\\n              />\\n\\n              \x3c!-- Transparent Hover Area (UX optimization) --\x3e\\n              <rect\\n                [attr.x]=\\"tick.x\\"\\n                [attr.y]=\\"0\\"\\n                [attr.width]=\\"tick.cellWidth\\"\\n                [attr.height]=\\"innerH()\\"\\n                fill=\\"transparent\\"\\n                style=\\"cursor: pointer;\\"\\n                (mouseenter)=\\"onTickHover($event, tick.raw, i)\\"\\n                (mousemove)=\\"onTickHover($event, tick.raw, i)\\"\\n              />\\n            }\\n\\n            \x3c!-- Base axes borders --\x3e\\n            <line x1=\\"0\\" [attr.x2]=\\"innerW()\\" [attr.y1]=\\"innerH()\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n            <line x1=\\"0\\" x2=\\"0\\" y1=\\"0\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n          </g>\\n        </svg>\\n\\n        \x3c!-- Tooltip --\x3e\\n        @if (tooltip(); as t) {\\n          <div class=\\"chart-tooltip\\" [style.left.px]=\\"t.x\\" [style.top.px]=\\"t.y\\">\\n            <div class=\\"tooltip-header\\">{{ formatDate(t.date) }}</div>\\n            <div class=\\"tooltip-body\\">\\n              <div class=\\"tooltip-direction\\" [style.color]=\\"t.direction === \'Bullish\' ? \'#10b981\' : \'#ef4444\'\\">\\n                <strong>{{ t.direction }}</strong> ({{ t.changePct }})\\n              </div>\\n              <div class=\\"tooltip-val\\">\\n                <span>High:</span>\\n                <strong>{{ fmtNum(t.high) }}</strong>\\n              </div>\\n              <div class=\\"tooltip-val\\" style=\\"color: #38bdf8;\\">\\n                <span>Close:</span>\\n                <strong>{{ fmtNum(t.close) }}</strong>\\n              </div>\\n              <div class=\\"tooltip-val\\">\\n                <span>Low:</span>\\n                <strong>{{ fmtNum(t.low) }}</strong>\\n              </div>\\n            </div>\\n          </div>\\n        }\\n      </div>\\n    </div>\\n  `,\\n  styles: [`\\n    :host {\\n      display: block;\\n      width: 100%;\\n    }\\n    .ngx-hlc-chart {\\n      position: relative;\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n    }\\n    .chart-svg-container {\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .axis-label {\\n      font-size: 10px;\\n      fill: #64748b;\\n      font-weight: 500;\\n    }\\n    .hlc-line {\\n      transition: stroke-width 0.15s, stroke 0.15s;\\n    }\\n    .crosshair-line {\\n      pointer-events: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 11px;\\n      z-index: 100;\\n      min-width: 155px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      transition: left 0.08s ease-out, top 0.08s ease-out;\\n    }\\n    .tooltip-header {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tooltip-direction {\\n      font-size: 10px;\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      text-transform: uppercase;\\n      letter-spacing: 0.3px;\\n    }\\n    .tooltip-body {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 4px;\\n    }\\n    .tooltip-val {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: 16px;\\n      color: rgba(248, 250, 252, 0.85);\\n    }\\n    .tooltip-val strong {\\n      color: #f8fafc;\\n      font-family: monospace;\\n      font-weight: 700;\\n    }\\n\\n    /* Export styles removed */\\n    .chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }\\n  `]\\n})\\nexport class HLCChartComponent {\\n  private readonly exportSvc = inject(ChartExportService);\\n\\n  readonly PAD_LEFT = 52;\\n  readonly PAD_TOP = 20;\\n  readonly PAD_RIGHT = 24;\\n  readonly PAD_BOTTOM = 36;\\n\\n  data = input.required<HLCItem[]>();\\n  height = input<number>(300);\\n  showGrid = input<boolean>(true);\\n  showLabels = input<boolean>(true);\\n  showExport = input<boolean>(false);\\n  colors = input<string[]>(CHART_COLORS);\\n  bullishColor = input<string>(\'#10b981\');\\n  bearishColor = input<string>(\'#ef4444\');\\n\\n  hoveredIndex = signal<number | null>(null);\\n  tooltip = signal<{\\n    x: number;\\n    y: number;\\n    date: string | Date;\\n    high: number;\\n    low: number;\\n    close: number;\\n    direction: \'Bullish\' | \'Bearish\';\\n    changePct: string;\\n  } | null>(null);\\n\\n  containerWidth = signal<number>(600);\\n  svgEl = viewChild<ElementRef<SVGElement>>(\'svgEl\');\\n  private container = viewChild<ElementRef>(\'container\');\\n\\n  constructor() {\\n    const hostEl = inject(ElementRef).nativeElement;\\n    if (typeof ResizeObserver !== \'undefined\') {\\n      const resizeObserver = new ResizeObserver(entries => {\\n        if (!entries || entries.length === 0) return;\\n        const width = entries[0].contentRect.width;\\n        if (width > 0) {\\n          // Subtract padding\\n          this.containerWidth.set(width - 32);\\n        }\\n      });\\n      resizeObserver.observe(hostEl);\\n      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());\\n    }\\n  }\\n\\n  innerW = computed(() => Math.max(200, this.containerWidth() - this.PAD_LEFT - this.PAD_RIGHT));\\n  innerH = computed(() => Math.max(100, this.height() - this.PAD_TOP - this.PAD_BOTTOM));\\n\\n  yMin = computed(() => {\\n    const items = this.data();\\n    if (items.length === 0) return 0;\\n    const lows = items.map(d => d.low);\\n    const minVal = Math.min(...lows);\\n    return minVal * 0.99; // 1% safety margin\\n  });\\n\\n  yMax = computed(() => {\\n    const items = this.data();\\n    if (items.length === 0) return 100;\\n    const highs = items.map(d => d.high);\\n    const maxVal = Math.max(...highs);\\n    return maxVal * 1.01; // 1% safety margin\\n  });\\n\\n  yTicks = computed(() => niceTicks(this.yMin(), this.yMax(), 5));\\n\\n  xPos(index: number): number {\\n    const count = this.data().length || 1;\\n    const step = this.innerW() / count;\\n    return index * step;\\n  }\\n\\n  yPos(y: number): number {\\n    return scale(y, this.yMin(), this.yMax(), this.innerH(), 0);\\n  }\\n\\n  tickWidth(): number {\\n    const count = this.data().length || 1;\\n    return (this.innerW() / count) * 0.6; // 60% of cell width\\n  }\\n\\n  computedTicks = computed(() => {\\n    const items = this.data();\\n    const count = items.length;\\n    if (count === 0) return [];\\n    const width = this.tickWidth();\\n    const cellWidth = this.innerW() / count;\\n\\n    return items.map((item, idx) => {\\n      const x = this.xPos(idx);\\n      const centerX = x + cellWidth / 2;\\n\\n      const yHigh = this.yPos(item.high);\\n      const yLow = this.yPos(item.low);\\n      const yClose = this.yPos(item.close);\\n\\n      let isBullish = true;\\n      if (idx > 0) {\\n        isBullish = item.close >= items[idx - 1].close;\\n      }\\n      const color = isBullish ? this.bullishColor() : this.bearishColor();\\n\\n      return {\\n        x,\\n        centerX,\\n        cellWidth,\\n        width,\\n        yHigh,\\n        yLow,\\n        yClose,\\n        color,\\n        isBullish,\\n        raw: item\\n      };\\n    });\\n  });\\n\\n  shouldShowXLabel(index: number): boolean {\\n    const count = this.data().length;\\n    if (count <= 10) return true;\\n    if (count <= 25) return index % 2 === 0;\\n    if (count <= 50) return index % 5 === 0;\\n    return index % 10 === 0;\\n  }\\n\\n  onTickHover(event: MouseEvent, item: HLCItem, index: number) {\\n    this.hoveredIndex.set(index);\\n    const containerEl = this.container()?.nativeElement;\\n    if (!containerEl) return;\\n    const rect = containerEl.getBoundingClientRect();\\n    const tooltipX = event.clientX - rect.left;\\n    const tooltipY = event.clientY - rect.top;\\n\\n    const items = this.data();\\n    let isBullish = true;\\n    let changePct = \'0.00%\';\\n    if (index > 0) {\\n      const prev = items[index - 1];\\n      isBullish = item.close >= prev.close;\\n      const change = item.close - prev.close;\\n      changePct = ((change / prev.close) * 100).toFixed(2) + \'%\';\\n    }\\n\\n    this.tooltip.set({\\n      x: tooltipX,\\n      y: tooltipY,\\n      date: item.date,\\n      high: item.high,\\n      low: item.low,\\n      close: item.close,\\n      direction: isBullish ? \'Bullish\' : \'Bearish\',\\n      changePct\\n    });\\n  }\\n\\n  formatDate(d: string | Date): string {\\n    if (d instanceof Date) {\\n      return d.toLocaleDateString(undefined, { month: \'short\', day: \'numeric\' });\\n    }\\n    return String(d);\\n  }\\n\\n  onExport(type: ExportFormat): void {\\n    if (type === \'json\') this.exportToJson();\\n    else if (type === \'csv\') this.exportToCsv();\\n    else if (type === \'svg\') this.exportToSvg();\\n    else if (type === \'pdf\') this.exportToPdf();\\n  }\\n\\n  exportToCsv(): void {\\n    const items = this.data();\\n    if (!items.length) return;\\n    const headers = [\'Date\', \'High\', \'Low\', \'Close\'];\\n    const rows = items.map(item => [this.formatDate(item.date), item.high, item.low, item.close]);\\n    this.exportSvc.downloadCsv(headers, rows, \'hlc-chart-data.csv\');\\n  }\\n\\n  exportToJson(): void {\\n    const items = this.data();\\n    if (!items.length) return;\\n    this.exportSvc.downloadJson(items, \'hlc-chart-data.json\');\\n  }\\n\\n  exportToSvg(): void {\\n    this.exportSvc.downloadSvg(this.svgEl()?.nativeElement, \'hlc-chart.svg\');\\n  }\\n\\n  exportToPdf(): void {\\n    this.exportSvc.downloadPdf(this.svgEl()?.nativeElement, \'HLC Chart\', \'hlc-chart.pdf\');\\n  }\\n\\n  readonly fmtNum = fmtNum;\\n}\\n","assetsDirs":[],"styleUrlsData":"","stylesData":"\\n    :host {\\n      display: block;\\n      width: 100%;\\n    }\\n    .ngx-hlc-chart {\\n      position: relative;\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n    }\\n    .chart-svg-container {\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .axis-label {\\n      font-size: 10px;\\n      fill: #64748b;\\n      font-weight: 500;\\n    }\\n    .hlc-line {\\n      transition: stroke-width 0.15s, stroke 0.15s;\\n    }\\n    .crosshair-line {\\n      pointer-events: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 11px;\\n      z-index: 100;\\n      min-width: 155px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      transition: left 0.08s ease-out, top 0.08s ease-out;\\n    }\\n    .tooltip-header {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tooltip-direction {\\n      font-size: 10px;\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      text-transform: uppercase;\\n      letter-spacing: 0.3px;\\n    }\\n    .tooltip-body {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 4px;\\n    }\\n    .tooltip-val {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: 16px;\\n      color: rgba(248, 250, 252, 0.85);\\n    }\\n    .tooltip-val strong {\\n      color: #f8fafc;\\n      font-family: monospace;\\n      font-weight: 700;\\n    }\\n\\n    /* Export styles removed */\\n    .chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }\\n  \\n","constructorObj":{"name":"constructor","description":"","deprecated":false,"deprecationMessage":"","args":[],"line":294},"extends":[]},{"name":"HollowCandlestickChartComponent","id":"component-HollowCandlestickChartComponent-c321bd2aae8b03de3a869e457f85d7f0db9d1d64042f9011cc89d6b952bd944785211e6b0b154fb67bc1e4a3d4e94d911361b534a9b78c2236b4867e66c44371","file":"projects/ngx-core-components/charts/hollow-candlestick-chart/hollow-candlestick-chart.component.ts","changeDetection":"ChangeDetectionStrategy.OnPush","encapsulation":[],"entryComponents":[],"inputs":[],"outputs":[],"providers":[],"selector":"ngx-hollow-candlestick-chart","styleUrls":[],"styles":["\\n    :host {\\n      display: block;\\n      width: 100%;\\n    }\\n    .ngx-hollow-candlestick-chart {\\n      position: relative;\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n    }\\n    .chart-svg-container {\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .axis-label {\\n      font-size: 10px;\\n      fill: #64748b;\\n      font-weight: 500;\\n    }\\n\\n    @keyframes candleGrow {\\n      from { transform: scaleY(0); opacity: 0; }\\n      to { transform: scaleY(1); opacity: 1; }\\n    }\\n\\n    .candle-rect {\\n      cursor: pointer;\\n      transition: fill 0.15s, stroke-width 0.15s, filter 0.15s;\\n      animation: candleGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;\\n    }\\n    .candle-rect.hovered {\\n      filter: brightness(1.05) drop-shadow(0 4px 8px rgba(0,0,0,0.15));\\n      stroke-width: 2.5px !important;\\n    }\\n    .crosshair-line {\\n      pointer-events: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 11px;\\n      z-index: 100;\\n      min-width: 165px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      transition: left 0.08s ease-out, top 0.08s ease-out;\\n    }\\n    .tooltip-header {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tooltip-direction {\\n      font-size: 10px;\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      text-transform: uppercase;\\n      letter-spacing: 0.3px;\\n    }\\n    .tooltip-body {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 4px;\\n    }\\n    .tooltip-val {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: 16px;\\n      color: rgba(248, 250, 252, 0.85);\\n    }\\n    .tooltip-val strong {\\n      color: #f8fafc;\\n      font-family: monospace;\\n      font-weight: 700;\\n    }\\n\\n    /* Export styles removed */\\n    .chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }\\n  "],"template":"<div class=\\"ngx-hollow-candlestick-chart\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n  \x3c!-- Toolbar with Export option --\x3e\\n  <div class=\\"chart-header\\" (mousemove)=\\"$event.stopPropagation()\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n    <div class=\\"chart-title-space\\"></div>\\n    @if (showExport()) {\\n      <ngx-chart-export-menu (exportClicked)=\\"onExport($event)\\" />\\n    }\\n  </div>\\n\\n  <div class=\\"chart-svg-container\\" #container>\\n    <svg\\n      #svgEl\\n      [attr.width]=\\"\'100%\'\\"\\n      [attr.height]=\\"height()\\"\\n      class=\\"chart-svg\\"\\n    >\\n      <g [attr.transform]=\\"\'translate(\' + PAD_LEFT + \',\' + PAD_TOP + \')\'\\">\\n        \x3c!-- Grid Lines (Horizontal) --\x3e\\n        @if (showGrid()) {\\n          @for (tick of yTicks(); track tick) {\\n            <line\\n              [attr.x1]=\\"0\\"\\n              [attr.x2]=\\"innerW()\\"\\n              [attr.y1]=\\"yPos(tick)\\"\\n              [attr.y2]=\\"yPos(tick)\\"\\n              stroke=\\"var(--ngx-chart-grid, #ebedf0)\\"\\n              stroke-dasharray=\\"3,3\\"\\n            />\\n          }\\n        }\\n\\n        \x3c!-- Y-Axis Labels --\x3e\\n        @if (showLabels()) {\\n          @for (tick of yTicks(); track tick) {\\n            <text\\n              x=\\"-10\\"\\n              [attr.y]=\\"yPos(tick) + 4\\"\\n              class=\\"axis-label y\\"\\n              text-anchor=\\"end\\"\\n            >{{ fmtNum(tick) }}</text>\\n          }\\n        }\\n\\n        \x3c!-- X-Axis Labels --\x3e\\n        @if (showLabels()) {\\n          @for (item of data(); track $index; let i = $index) {\\n            @if (shouldShowXLabel(i)) {\\n              <text\\n                [attr.x]=\\"xPos(i) + candleWidth() / 2\\"\\n                [attr.y]=\\"innerH() + 20\\"\\n                class=\\"axis-label x\\"\\n                text-anchor=\\"middle\\"\\n              >{{ formatDate(item.date) }}</text>\\n            }\\n          }\\n        }\\n\\n        \x3c!-- Active Crosshair --\x3e\\n        @if (hoveredIndex() !== null) {\\n          @if (computedCandles()[hoveredIndex()!]; as candle) {\\n            <line\\n              [attr.x1]=\\"0\\"\\n              [attr.x2]=\\"innerW()\\"\\n              [attr.y1]=\\"candle.yClose\\"\\n              [attr.y2]=\\"candle.yClose\\"\\n              stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n              stroke-width=\\"1.2\\"\\n              stroke-dasharray=\\"3,3\\"\\n              class=\\"crosshair-line\\"\\n            />\\n            <line\\n              [attr.x1]=\\"candle.centerX\\"\\n              [attr.x2]=\\"candle.centerX\\"\\n              [attr.y1]=\\"0\\"\\n              [attr.y2]=\\"innerH()\\"\\n              stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n              stroke-width=\\"1.2\\"\\n              stroke-dasharray=\\"3,3\\"\\n              class=\\"crosshair-line\\"\\n            />\\n          }\\n        }\\n\\n        \x3c!-- Hollow Candlesticks --\x3e\\n        @for (candle of computedCandles(); track $index; let i = $index) {\\n          \x3c!-- Upper Wick (High to Top of Body) --\x3e\\n          <line\\n            [attr.x1]=\\"candle.centerX\\"\\n            [attr.y1]=\\"candle.yHigh\\"\\n            [attr.x2]=\\"candle.centerX\\"\\n            [attr.y2]=\\"candle.yBodyTop\\"\\n            [attr.stroke]=\\"candle.color\\"\\n            stroke-width=\\"1.5\\"\\n          />\\n\\n          \x3c!-- Lower Wick (Bottom of Body to Low) --\x3e\\n          <line\\n            [attr.x1]=\\"candle.centerX\\"\\n            [attr.y1]=\\"candle.yBodyBottom\\"\\n            [attr.x2]=\\"candle.centerX\\"\\n            [attr.y2]=\\"candle.yLow\\"\\n            [attr.stroke]=\\"candle.color\\"\\n            stroke-width=\\"1.5\\"\\n          />\\n\\n          \x3c!-- Candle Body Rect (Hollow vs Solid) --\x3e\\n          <rect\\n            [attr.x]=\\"candle.x\\"\\n            [attr.y]=\\"candle.y\\"\\n            [attr.width]=\\"candle.width\\"\\n            [attr.height]=\\"candle.rectH\\"\\n            [attr.fill]=\\"candle.isHollow ? \'none\' : candle.color\\"\\n            [attr.stroke]=\\"candle.color\\"\\n            [attr.stroke-width]=\\"candle.isHollow ? 2 : 1\\"\\n            class=\\"candle-rect\\"\\n            [class.hovered]=\\"hoveredIndex() === i\\"\\n            [style.transform-origin]=\\"candle.centerX + \'px \' + candle.yOpen + \'px\'\\"\\n            [style.animation-delay]=\\"i * 0.02 + \'s\'\\"\\n            (mouseenter)=\\"onCandleHover($event, candle.raw, i)\\"\\n            (mousemove)=\\"onCandleHover($event, candle.raw, i)\\"\\n          />\\n        }\\n\\n        \x3c!-- Base axes borders --\x3e\\n        <line x1=\\"0\\" [attr.x2]=\\"innerW()\\" [attr.y1]=\\"innerH()\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n        <line x1=\\"0\\" x2=\\"0\\" y1=\\"0\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n      </g>\\n    </svg>\\n\\n    \x3c!-- Tooltip --\x3e\\n    @if (tooltip(); as t) {\\n      <div class=\\"chart-tooltip\\" [style.left.px]=\\"t.x\\" [style.top.px]=\\"t.y\\">\\n        <div class=\\"tooltip-header\\">{{ formatDate(t.date) }}</div>\\n        <div class=\\"tooltip-body\\">\\n          <div class=\\"tooltip-direction\\" [style.color]=\\"t.isUp ? \'#10b981\' : \'#ef4444\'\\">\\n            <strong>{{ t.direction }}</strong> ({{ t.changePct }})\\n          </div>\\n          <div class=\\"tooltip-val\\" style=\\"font-size: 10px; color: rgba(255, 255, 255, 0.6); margin-bottom: 2px;\\">\\n            <span>Type:</span>\\n            <strong>{{ t.hollowText }}</strong>\\n          </div>\\n          <div class=\\"tooltip-val\\">\\n            <span>High:</span>\\n            <strong>{{ fmtNum(t.high) }}</strong>\\n          </div>\\n          <div class=\\"tooltip-val\\" style=\\"color: #60a5fa;\\">\\n            <span>Open:</span>\\n            <strong>{{ fmtNum(t.open) }}</strong>\\n          </div>\\n          <div class=\\"tooltip-val\\" style=\\"color: #38bdf8;\\">\\n            <span>Close:</span>\\n            <strong>{{ fmtNum(t.close) }}</strong>\\n          </div>\\n          <div class=\\"tooltip-val\\">\\n            <span>Low:</span>\\n            <strong>{{ fmtNum(t.low) }}</strong>\\n          </div>\\n        </div>\\n      </div>\\n    }\\n  </div>\\n</div>\\n","templateUrl":[],"viewProviders":[],"hostDirectives":[],"inputsClass":[{"name":"bearishColor","defaultValue":"\'#ef4444\'","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":302,"required":false},{"name":"bullishColor","defaultValue":"\'#10b981\'","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":301,"required":false},{"name":"colors","defaultValue":"CHART_COLORS","deprecated":false,"deprecationMessage":"","type":"string[]","indexKey":"","optional":false,"description":"","line":300,"required":false},{"name":"data","deprecated":false,"deprecationMessage":"","type":"CandlestickItem[]","indexKey":"","optional":false,"description":"","line":295,"required":true},{"name":"height","defaultValue":"300","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":296,"required":false},{"name":"showExport","defaultValue":"false","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":299,"required":false},{"name":"showGrid","defaultValue":"true","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":297,"required":false},{"name":"showLabels","defaultValue":"true","deprecated":false,"deprecationMessage":"","type":"boolean","indexKey":"","optional":false,"description":"","line":298,"required":false}],"outputsClass":[],"propertiesClass":[{"name":"computedCandles","defaultValue":"computed(() => {\\n    const items = this.data();\\n    const count = items.length;\\n    if (count === 0) return [];\\n    const width = this.candleWidth();\\n\\n    return items.map((item, idx) => {\\n      const x = this.xPos(idx);\\n      const centerX = x + width / 2;\\n\\n      const yOpen = this.yPos(item.open);\\n      const yClose = this.yPos(item.close);\\n      const yHigh = this.yPos(item.high);\\n      const yLow = this.yPos(item.low);\\n\\n      const y = Math.min(yOpen, yClose);\\n      const rectH = Math.max(2, Math.abs(yOpen - yClose));\\n\\n      // Color (compare close to previous close)\\n      let isUp = true;\\n      if (idx > 0) {\\n        isUp = item.close >= items[idx - 1].close;\\n      }\\n      const color = isUp ? this.bullishColor() : this.bearishColor();\\n\\n      // Hollow/Solid (compare close to open of current day)\\n      const isHollow = item.close >= item.open;\\n\\n      return {\\n        x,\\n        centerX,\\n        width,\\n        yHigh,\\n        yLow,\\n        yOpen,\\n        yClose,\\n        y,\\n        rectH,\\n        yBodyTop: y,\\n        yBodyBottom: y + rectH,\\n        color,\\n        isUp,\\n        isHollow,\\n        raw: item\\n      };\\n    });\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":375},{"name":"container","defaultValue":"viewChild<ElementRef>(\'container\')","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":321,"modifierKind":[123]},{"name":"containerWidth","defaultValue":"signal<number>(600)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":319},{"name":"exportSvc","defaultValue":"inject(ChartExportService)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":288,"modifierKind":[123,148]},{"name":"fmtNum","defaultValue":"fmtNum","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":508,"modifierKind":[148]},{"name":"hoveredIndex","defaultValue":"signal<number | null>(null)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":304},{"name":"innerH","defaultValue":"computed(() => Math.max(100, this.height() - this.PAD_TOP - this.PAD_BOTTOM))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":340},{"name":"innerW","defaultValue":"computed(() => Math.max(200, this.containerWidth() - this.PAD_LEFT - this.PAD_RIGHT))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":339},{"name":"PAD_BOTTOM","defaultValue":"36","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":293,"modifierKind":[148]},{"name":"PAD_LEFT","defaultValue":"52","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":290,"modifierKind":[148]},{"name":"PAD_RIGHT","defaultValue":"24","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":292,"modifierKind":[148]},{"name":"PAD_TOP","defaultValue":"20","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":291,"modifierKind":[148]},{"name":"svgEl","defaultValue":"viewChild<ElementRef<SVGElement>>(\'svgEl\')","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":320},{"name":"tooltip","defaultValue":"signal<{\\n    x: number;\\n    y: number;\\n    date: string | Date;\\n    open: number;\\n    high: number;\\n    low: number;\\n    close: number;\\n    isUp: boolean;\\n    direction: string;\\n    hollowText: string;\\n    changePct: string;\\n  } | null>(null)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":305},{"name":"yMax","defaultValue":"computed(() => {\\n    const items = this.data();\\n    if (items.length === 0) return 100;\\n    const highs = items.map(d => d.high);\\n    const maxVal = Math.max(...highs);\\n    return maxVal * 1.01; // 1% safety margin\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":350},{"name":"yMin","defaultValue":"computed(() => {\\n    const items = this.data();\\n    if (items.length === 0) return 0;\\n    const lows = items.map(d => d.low);\\n    const minVal = Math.min(...lows);\\n    return minVal * 0.99; // 1% safety margin\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":342},{"name":"yTicks","defaultValue":"computed(() => niceTicks(this.yMin(), this.yMax(), 5))","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":358}],"methodsClass":[{"name":"candleWidth","args":[],"optional":false,"returnType":"number","typeParameters":[],"line":370,"deprecated":false,"deprecationMessage":""},{"name":"exportToCsv","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":486,"deprecated":false,"deprecationMessage":""},{"name":"exportToJson","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":494,"deprecated":false,"deprecationMessage":""},{"name":"exportToPdf","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":504,"deprecated":false,"deprecationMessage":""},{"name":"exportToSvg","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":500,"deprecated":false,"deprecationMessage":""},{"name":"formatDate","args":[{"name":"d","type":"string | Date","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"string","typeParameters":[],"line":472,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"d","type":"string | Date","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onCandleHover","args":[{"name":"event","type":"MouseEvent","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""},{"name":"item","type":"CandlestickItem","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""},{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":431,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"event","type":"MouseEvent","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}},{"name":"item","type":"CandlestickItem","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}},{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"onExport","args":[{"name":"type","type":"ExportFormat","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"void","typeParameters":[],"line":479,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"type","type":"ExportFormat","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"shouldShowXLabel","args":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"boolean","typeParameters":[],"line":423,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"xPos","args":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"number","typeParameters":[],"line":360,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"index","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]},{"name":"yPos","args":[{"name":"y","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":""}],"optional":false,"returnType":"number","typeParameters":[],"line":366,"deprecated":false,"deprecationMessage":"","jsdoctags":[{"name":"y","type":"number","optional":false,"dotDotDotToken":false,"deprecated":false,"deprecationMessage":"","tagName":{"text":"param"}}]}],"deprecated":false,"deprecationMessage":"","hostBindings":[],"hostListeners":[],"standalone":true,"imports":[{"name":"ChartExportMenuComponent","type":"component"}],"description":"","rawdescription":"\\n","type":"component","sourceCode":"import {\\n  Component, ChangeDetectionStrategy, input, computed, signal,\\n  ElementRef, inject, DestroyRef, viewChild\\n} from \'@angular/core\';\\nimport { ChartExportService } from \'../shared/chart-export.service\';\\nimport { ChartExportMenuComponent } from \'../shared/chart-export-menu.component\';\\nimport type { ExportFormat } from \'../shared/chart-export-menu.component\';\\nimport { niceTicks, scale, fmtNum, CHART_COLORS } from \'../shared/chart-utils\';\\n\\nexport interface CandlestickItem {\\n  date: string | Date;\\n  open: number;\\n  high: number;\\n  low: number;\\n  close: number;\\n}\\n\\n@Component({\\n  selector: \'ngx-hollow-candlestick-chart\',\\n  standalone: true,\\n  imports: [ChartExportMenuComponent],\\n  changeDetection: ChangeDetectionStrategy.OnPush,\\n  template: `\\n    <div class=\\"ngx-hollow-candlestick-chart\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n      \x3c!-- Toolbar with Export option --\x3e\\n      <div class=\\"chart-header\\" (mousemove)=\\"$event.stopPropagation()\\" (mouseleave)=\\"hoveredIndex.set(null); tooltip.set(null)\\">\\n        <div class=\\"chart-title-space\\"></div>\\n        @if (showExport()) {\\n          <ngx-chart-export-menu (exportClicked)=\\"onExport($event)\\" />\\n        }\\n      </div>\\n\\n      <div class=\\"chart-svg-container\\" #container>\\n        <svg\\n          #svgEl\\n          [attr.width]=\\"\'100%\'\\"\\n          [attr.height]=\\"height()\\"\\n          class=\\"chart-svg\\"\\n        >\\n          <g [attr.transform]=\\"\'translate(\' + PAD_LEFT + \',\' + PAD_TOP + \')\'\\">\\n            \x3c!-- Grid Lines (Horizontal) --\x3e\\n            @if (showGrid()) {\\n              @for (tick of yTicks(); track tick) {\\n                <line\\n                  [attr.x1]=\\"0\\"\\n                  [attr.x2]=\\"innerW()\\"\\n                  [attr.y1]=\\"yPos(tick)\\"\\n                  [attr.y2]=\\"yPos(tick)\\"\\n                  stroke=\\"var(--ngx-chart-grid, #ebedf0)\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                />\\n              }\\n            }\\n\\n            \x3c!-- Y-Axis Labels --\x3e\\n            @if (showLabels()) {\\n              @for (tick of yTicks(); track tick) {\\n                <text\\n                  x=\\"-10\\"\\n                  [attr.y]=\\"yPos(tick) + 4\\"\\n                  class=\\"axis-label y\\"\\n                  text-anchor=\\"end\\"\\n                >{{ fmtNum(tick) }}</text>\\n              }\\n            }\\n\\n            \x3c!-- X-Axis Labels --\x3e\\n            @if (showLabels()) {\\n              @for (item of data(); track $index; let i = $index) {\\n                @if (shouldShowXLabel(i)) {\\n                  <text\\n                    [attr.x]=\\"xPos(i) + candleWidth() / 2\\"\\n                    [attr.y]=\\"innerH() + 20\\"\\n                    class=\\"axis-label x\\"\\n                    text-anchor=\\"middle\\"\\n                  >{{ formatDate(item.date) }}</text>\\n                }\\n              }\\n            }\\n\\n            \x3c!-- Active Crosshair --\x3e\\n            @if (hoveredIndex() !== null) {\\n              @if (computedCandles()[hoveredIndex()!]; as candle) {\\n                <line\\n                  [attr.x1]=\\"0\\"\\n                  [attr.x2]=\\"innerW()\\"\\n                  [attr.y1]=\\"candle.yClose\\"\\n                  [attr.y2]=\\"candle.yClose\\"\\n                  stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n                  stroke-width=\\"1.2\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                  class=\\"crosshair-line\\"\\n                />\\n                <line\\n                  [attr.x1]=\\"candle.centerX\\"\\n                  [attr.x2]=\\"candle.centerX\\"\\n                  [attr.y1]=\\"0\\"\\n                  [attr.y2]=\\"innerH()\\"\\n                  stroke=\\"rgba(100, 116, 139, 0.25)\\"\\n                  stroke-width=\\"1.2\\"\\n                  stroke-dasharray=\\"3,3\\"\\n                  class=\\"crosshair-line\\"\\n                />\\n              }\\n            }\\n\\n            \x3c!-- Hollow Candlesticks --\x3e\\n            @for (candle of computedCandles(); track $index; let i = $index) {\\n              \x3c!-- Upper Wick (High to Top of Body) --\x3e\\n              <line\\n                [attr.x1]=\\"candle.centerX\\"\\n                [attr.y1]=\\"candle.yHigh\\"\\n                [attr.x2]=\\"candle.centerX\\"\\n                [attr.y2]=\\"candle.yBodyTop\\"\\n                [attr.stroke]=\\"candle.color\\"\\n                stroke-width=\\"1.5\\"\\n              />\\n\\n              \x3c!-- Lower Wick (Bottom of Body to Low) --\x3e\\n              <line\\n                [attr.x1]=\\"candle.centerX\\"\\n                [attr.y1]=\\"candle.yBodyBottom\\"\\n                [attr.x2]=\\"candle.centerX\\"\\n                [attr.y2]=\\"candle.yLow\\"\\n                [attr.stroke]=\\"candle.color\\"\\n                stroke-width=\\"1.5\\"\\n              />\\n\\n              \x3c!-- Candle Body Rect (Hollow vs Solid) --\x3e\\n              <rect\\n                [attr.x]=\\"candle.x\\"\\n                [attr.y]=\\"candle.y\\"\\n                [attr.width]=\\"candle.width\\"\\n                [attr.height]=\\"candle.rectH\\"\\n                [attr.fill]=\\"candle.isHollow ? \'none\' : candle.color\\"\\n                [attr.stroke]=\\"candle.color\\"\\n                [attr.stroke-width]=\\"candle.isHollow ? 2 : 1\\"\\n                class=\\"candle-rect\\"\\n                [class.hovered]=\\"hoveredIndex() === i\\"\\n                [style.transform-origin]=\\"candle.centerX + \'px \' + candle.yOpen + \'px\'\\"\\n                [style.animation-delay]=\\"i * 0.02 + \'s\'\\"\\n                (mouseenter)=\\"onCandleHover($event, candle.raw, i)\\"\\n                (mousemove)=\\"onCandleHover($event, candle.raw, i)\\"\\n              />\\n            }\\n\\n            \x3c!-- Base axes borders --\x3e\\n            <line x1=\\"0\\" [attr.x2]=\\"innerW()\\" [attr.y1]=\\"innerH()\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n            <line x1=\\"0\\" x2=\\"0\\" y1=\\"0\\" [attr.y2]=\\"innerH()\\" stroke=\\"var(--ngx-chart-axis, #ced4da)\\"/>\\n          </g>\\n        </svg>\\n\\n        \x3c!-- Tooltip --\x3e\\n        @if (tooltip(); as t) {\\n          <div class=\\"chart-tooltip\\" [style.left.px]=\\"t.x\\" [style.top.px]=\\"t.y\\">\\n            <div class=\\"tooltip-header\\">{{ formatDate(t.date) }}</div>\\n            <div class=\\"tooltip-body\\">\\n              <div class=\\"tooltip-direction\\" [style.color]=\\"t.isUp ? \'#10b981\' : \'#ef4444\'\\">\\n                <strong>{{ t.direction }}</strong> ({{ t.changePct }})\\n              </div>\\n              <div class=\\"tooltip-val\\" style=\\"font-size: 10px; color: rgba(255, 255, 255, 0.6); margin-bottom: 2px;\\">\\n                <span>Type:</span>\\n                <strong>{{ t.hollowText }}</strong>\\n              </div>\\n              <div class=\\"tooltip-val\\">\\n                <span>High:</span>\\n                <strong>{{ fmtNum(t.high) }}</strong>\\n              </div>\\n              <div class=\\"tooltip-val\\" style=\\"color: #60a5fa;\\">\\n                <span>Open:</span>\\n                <strong>{{ fmtNum(t.open) }}</strong>\\n              </div>\\n              <div class=\\"tooltip-val\\" style=\\"color: #38bdf8;\\">\\n                <span>Close:</span>\\n                <strong>{{ fmtNum(t.close) }}</strong>\\n              </div>\\n              <div class=\\"tooltip-val\\">\\n                <span>Low:</span>\\n                <strong>{{ fmtNum(t.low) }}</strong>\\n              </div>\\n            </div>\\n          </div>\\n        }\\n      </div>\\n    </div>\\n  `,\\n  styles: [`\\n    :host {\\n      display: block;\\n      width: 100%;\\n    }\\n    .ngx-hollow-candlestick-chart {\\n      position: relative;\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n    }\\n    .chart-svg-container {\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .axis-label {\\n      font-size: 10px;\\n      fill: #64748b;\\n      font-weight: 500;\\n    }\\n\\n    @keyframes candleGrow {\\n      from { transform: scaleY(0); opacity: 0; }\\n      to { transform: scaleY(1); opacity: 1; }\\n    }\\n\\n    .candle-rect {\\n      cursor: pointer;\\n      transition: fill 0.15s, stroke-width 0.15s, filter 0.15s;\\n      animation: candleGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;\\n    }\\n    .candle-rect.hovered {\\n      filter: brightness(1.05) drop-shadow(0 4px 8px rgba(0,0,0,0.15));\\n      stroke-width: 2.5px !important;\\n    }\\n    .crosshair-line {\\n      pointer-events: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 11px;\\n      z-index: 100;\\n      min-width: 165px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      transition: left 0.08s ease-out, top 0.08s ease-out;\\n    }\\n    .tooltip-header {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tooltip-direction {\\n      font-size: 10px;\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      text-transform: uppercase;\\n      letter-spacing: 0.3px;\\n    }\\n    .tooltip-body {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 4px;\\n    }\\n    .tooltip-val {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: 16px;\\n      color: rgba(248, 250, 252, 0.85);\\n    }\\n    .tooltip-val strong {\\n      color: #f8fafc;\\n      font-family: monospace;\\n      font-weight: 700;\\n    }\\n\\n    /* Export styles removed */\\n    .chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }\\n  `]\\n})\\nexport class HollowCandlestickChartComponent {\\n  private readonly exportSvc = inject(ChartExportService);\\n\\n  readonly PAD_LEFT = 52;\\n  readonly PAD_TOP = 20;\\n  readonly PAD_RIGHT = 24;\\n  readonly PAD_BOTTOM = 36;\\n\\n  data = input.required<CandlestickItem[]>();\\n  height = input<number>(300);\\n  showGrid = input<boolean>(true);\\n  showLabels = input<boolean>(true);\\n  showExport = input<boolean>(false);\\n  colors = input<string[]>(CHART_COLORS);\\n  bullishColor = input<string>(\'#10b981\');\\n  bearishColor = input<string>(\'#ef4444\');\\n\\n  hoveredIndex = signal<number | null>(null);\\n  tooltip = signal<{\\n    x: number;\\n    y: number;\\n    date: string | Date;\\n    open: number;\\n    high: number;\\n    low: number;\\n    close: number;\\n    isUp: boolean;\\n    direction: string;\\n    hollowText: string;\\n    changePct: string;\\n  } | null>(null);\\n\\n  containerWidth = signal<number>(600);\\n  svgEl = viewChild<ElementRef<SVGElement>>(\'svgEl\');\\n  private container = viewChild<ElementRef>(\'container\');\\n\\n  constructor() {\\n    const hostEl = inject(ElementRef).nativeElement;\\n    if (typeof ResizeObserver !== \'undefined\') {\\n      const resizeObserver = new ResizeObserver(entries => {\\n        if (!entries || entries.length === 0) return;\\n        const width = entries[0].contentRect.width;\\n        if (width > 0) {\\n          // Subtract padding\\n          this.containerWidth.set(width - 32);\\n        }\\n      });\\n      resizeObserver.observe(hostEl);\\n      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());\\n    }\\n  }\\n\\n  innerW = computed(() => Math.max(200, this.containerWidth() - this.PAD_LEFT - this.PAD_RIGHT));\\n  innerH = computed(() => Math.max(100, this.height() - this.PAD_TOP - this.PAD_BOTTOM));\\n\\n  yMin = computed(() => {\\n    const items = this.data();\\n    if (items.length === 0) return 0;\\n    const lows = items.map(d => d.low);\\n    const minVal = Math.min(...lows);\\n    return minVal * 0.99; // 1% safety margin\\n  });\\n\\n  yMax = computed(() => {\\n    const items = this.data();\\n    if (items.length === 0) return 100;\\n    const highs = items.map(d => d.high);\\n    const maxVal = Math.max(...highs);\\n    return maxVal * 1.01; // 1% safety margin\\n  });\\n\\n  yTicks = computed(() => niceTicks(this.yMin(), this.yMax(), 5));\\n\\n  xPos(index: number): number {\\n    const count = this.data().length || 1;\\n    const step = this.innerW() / count;\\n    return index * step + step * 0.15; // padding\\n  }\\n\\n  yPos(y: number): number {\\n    return scale(y, this.yMin(), this.yMax(), this.innerH(), 0);\\n  }\\n\\n  candleWidth(): number {\\n    const count = this.data().length || 1;\\n    return (this.innerW() / count) * 0.7; // 70% width\\n  }\\n\\n  computedCandles = computed(() => {\\n    const items = this.data();\\n    const count = items.length;\\n    if (count === 0) return [];\\n    const width = this.candleWidth();\\n\\n    return items.map((item, idx) => {\\n      const x = this.xPos(idx);\\n      const centerX = x + width / 2;\\n\\n      const yOpen = this.yPos(item.open);\\n      const yClose = this.yPos(item.close);\\n      const yHigh = this.yPos(item.high);\\n      const yLow = this.yPos(item.low);\\n\\n      const y = Math.min(yOpen, yClose);\\n      const rectH = Math.max(2, Math.abs(yOpen - yClose));\\n\\n      // Color (compare close to previous close)\\n      let isUp = true;\\n      if (idx > 0) {\\n        isUp = item.close >= items[idx - 1].close;\\n      }\\n      const color = isUp ? this.bullishColor() : this.bearishColor();\\n\\n      // Hollow/Solid (compare close to open of current day)\\n      const isHollow = item.close >= item.open;\\n\\n      return {\\n        x,\\n        centerX,\\n        width,\\n        yHigh,\\n        yLow,\\n        yOpen,\\n        yClose,\\n        y,\\n        rectH,\\n        yBodyTop: y,\\n        yBodyBottom: y + rectH,\\n        color,\\n        isUp,\\n        isHollow,\\n        raw: item\\n      };\\n    });\\n  });\\n\\n  shouldShowXLabel(index: number): boolean {\\n    const count = this.data().length;\\n    if (count <= 10) return true;\\n    if (count <= 25) return index % 2 === 0;\\n    if (count <= 50) return index % 5 === 0;\\n    return index % 10 === 0;\\n  }\\n\\n  onCandleHover(event: MouseEvent, item: CandlestickItem, index: number) {\\n    this.hoveredIndex.set(index);\\n    const containerEl = this.container()?.nativeElement;\\n    if (!containerEl) return;\\n    const rect = containerEl.getBoundingClientRect();\\n    const tooltipX = event.clientX - rect.left;\\n    const tooltipY = event.clientY - rect.top;\\n\\n    const items = this.data();\\n    let isUp = true;\\n    let changePct = \'0.00%\';\\n    if (index > 0) {\\n      const prev = items[index - 1];\\n      isUp = item.close >= prev.close;\\n      const change = item.close - prev.close;\\n      changePct = ((change / prev.close) * 100).toFixed(2) + \'%\';\\n    } else {\\n      isUp = item.close >= item.open;\\n      const change = item.close - item.open;\\n      changePct = ((change / item.open) * 100).toFixed(2) + \'%\';\\n    }\\n\\n    const direction = isUp ? \'Up vs Yesterday\' : \'Down vs Yesterday\';\\n    const isHollow = item.close >= item.open;\\n    const hollowText = isHollow ? \'Hollow (Bullish Day)\' : \'Solid (Bearish Day)\';\\n\\n    this.tooltip.set({\\n      x: tooltipX,\\n      y: tooltipY,\\n      date: item.date,\\n      open: item.open,\\n      high: item.high,\\n      low: item.low,\\n      close: item.close,\\n      isUp,\\n      direction,\\n      hollowText,\\n      changePct\\n    });\\n  }\\n\\n  formatDate(d: string | Date): string {\\n    if (d instanceof Date) {\\n      return d.toLocaleDateString(undefined, { month: \'short\', day: \'numeric\' });\\n    }\\n    return String(d);\\n  }\\n\\n  onExport(type: ExportFormat): void {\\n    if (type === \'json\') this.exportToJson();\\n    else if (type === \'csv\') this.exportToCsv();\\n    else if (type === \'svg\') this.exportToSvg();\\n    else if (type === \'pdf\') this.exportToPdf();\\n  }\\n\\n  exportToCsv(): void {\\n    const items = this.data();\\n    if (!items.length) return;\\n    const headers = [\'Date\', \'Open\', \'High\', \'Low\', \'Close\'];\\n    const rows = items.map(item => [this.formatDate(item.date), item.open, item.high, item.low, item.close]);\\n    this.exportSvc.downloadCsv(headers, rows, \'hollow-candlestick-data.csv\');\\n  }\\n\\n  exportToJson(): void {\\n    const items = this.data();\\n    if (!items.length) return;\\n    this.exportSvc.downloadJson(items, \'hollow-candlestick-data.json\');\\n  }\\n\\n  exportToSvg(): void {\\n    this.exportSvc.downloadSvg(this.svgEl()?.nativeElement, \'hollow-candlestick-chart.svg\');\\n  }\\n\\n  exportToPdf(): void {\\n    this.exportSvc.downloadPdf(this.svgEl()?.nativeElement, \'Hollow Candlestick Chart\', \'hollow-candlestick-chart.pdf\');\\n  }\\n\\n  readonly fmtNum = fmtNum;\\n}\\n","assetsDirs":[],"styleUrlsData":"","stylesData":"\\n    :host {\\n      display: block;\\n      width: 100%;\\n    }\\n    .ngx-hollow-candlestick-chart {\\n      position: relative;\\n      background: var(--ngx-chart-bg, #ffffff);\\n      border: 1px solid var(--border-color, #e2e8f0);\\n      border-radius: 16px;\\n      padding: 16px;\\n      box-sizing: border-box;\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n    }\\n    .chart-svg-container {\\n      position: relative;\\n      width: 100%;\\n    }\\n    .chart-svg {\\n      display: block;\\n      overflow: visible;\\n    }\\n    .axis-label {\\n      font-size: 10px;\\n      fill: #64748b;\\n      font-weight: 500;\\n    }\\n\\n    @keyframes candleGrow {\\n      from { transform: scaleY(0); opacity: 0; }\\n      to { transform: scaleY(1); opacity: 1; }\\n    }\\n\\n    .candle-rect {\\n      cursor: pointer;\\n      transition: fill 0.15s, stroke-width 0.15s, filter 0.15s;\\n      animation: candleGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;\\n    }\\n    .candle-rect.hovered {\\n      filter: brightness(1.05) drop-shadow(0 4px 8px rgba(0,0,0,0.15));\\n      stroke-width: 2.5px !important;\\n    }\\n    .crosshair-line {\\n      pointer-events: none;\\n    }\\n\\n    /* Glassmorphic Tooltip */\\n    .chart-tooltip {\\n      position: absolute;\\n      pointer-events: none;\\n      transform: translate(-50%, -100%) translateY(-10px);\\n      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));\\n      backdrop-filter: blur(12px);\\n      -webkit-backdrop-filter: blur(12px);\\n      color: var(--ngx-chart-tooltip-color, #f8fafc);\\n      padding: 10px 14px;\\n      border-radius: 10px;\\n      font-size: 11px;\\n      z-index: 100;\\n      min-width: 165px;\\n      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);\\n      border: 1px solid rgba(255, 255, 255, 0.1);\\n      transition: left 0.08s ease-out, top 0.08s ease-out;\\n    }\\n    .tooltip-header {\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      font-size: 12.5px;\\n      border-bottom: 1px solid rgba(255, 255, 255, 0.15);\\n      padding-bottom: 4px;\\n      color: #38bdf8;\\n    }\\n    .tooltip-direction {\\n      font-size: 10px;\\n      font-weight: 700;\\n      margin-bottom: 6px;\\n      text-transform: uppercase;\\n      letter-spacing: 0.3px;\\n    }\\n    .tooltip-body {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 4px;\\n    }\\n    .tooltip-val {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: 16px;\\n      color: rgba(248, 250, 252, 0.85);\\n    }\\n    .tooltip-val strong {\\n      color: #f8fafc;\\n      font-family: monospace;\\n      font-weight: 700;\\n    }\\n\\n    /* Export styles removed */\\n    .chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }\\n  \\n","constructorObj":{"name":"constructor","description":"","deprecated":false,"deprecationMessage":"","args":[],"line":321},"extends":[]},{"name":"ImageCompareComponent","id":"component-ImageCompareComponent-6a0355c3fc88ac9902051c27f972afa2e855c9389ebfe2549d152a2682a63d6e3a51642919756f60941dec939e571d8dab4a770884b8978136384303bdd9dc77","file":"projects/ngx-core-components/views/image-compare/image-compare.component.ts","changeDetection":"ChangeDetectionStrategy.OnPush","encapsulation":[],"entryComponents":[],"inputs":[],"outputs":[],"providers":[],"selector":"ngx-image-compare","styleUrls":[],"styles":["\\n    :host {\\n      display: block;\\n      width: 100%;\\n      user-select: none;\\n      -webkit-user-select: none;\\n    }\\n\\n    .ngx-image-compare {\\n      position: relative;\\n      width: 100%;\\n      height: 450px;\\n      border-radius: 16px;\\n      overflow: hidden;\\n      cursor: ew-resize;\\n      background: #f1f5f9;\\n      box-shadow: \\n        0 10px 25px -5px rgba(0, 0, 0, 0.05),\\n        0 8px 10px -6px rgba(0, 0, 0, 0.05);\\n      border: 1px solid rgba(0, 0, 0, 0.04);\\n      font-family: var(--ngx-font-family, system-ui, sans-serif);\\n      transition: box-shadow 0.2s ease;\\n    }\\n\\n    .ngx-image-compare:focus-visible {\\n      outline: none;\\n      box-shadow: 0 0 0 3px var(--primary-color, #3b82f6);\\n    }\\n\\n    .ngx-image-compare.dragging {\\n      cursor: ew-resize !important;\\n    }\\n\\n    .ngx-image-compare.dark {\\n      background: #0f172a;\\n      border-color: rgba(255, 255, 255, 0.06);\\n    }\\n\\n    /* Layers positioning */\\n    .ngx-image-compare__layer {\\n      position: absolute;\\n      top: 0;\\n      left: 0;\\n      width: 100%;\\n      height: 100%;\\n      overflow: hidden;\\n    }\\n\\n    .ngx-image-compare__layer.before {\\n      z-index: 2;\\n    }\\n\\n    .ngx-image-compare__layer.after {\\n      z-index: 1;\\n    }\\n\\n    .ngx-image-compare__image {\\n      width: 100%;\\n      height: 100%;\\n      object-fit: cover;\\n      display: block;\\n      pointer-events: none;\\n    }\\n\\n    /* Labels styling */\\n    .ngx-image-compare__label {\\n      position: absolute;\\n      bottom: 20px;\\n      padding: 6px 12px;\\n      font-size: 11px;\\n      font-weight: 700;\\n      text-transform: uppercase;\\n      letter-spacing: 0.5px;\\n      border-radius: 6px;\\n      background: rgba(255, 255, 255, 0.65);\\n      backdrop-filter: blur(8px);\\n      -webkit-backdrop-filter: blur(8px);\\n      border: 1px solid rgba(255, 255, 255, 0.4);\\n      color: #0f172a;\\n      z-index: 5;\\n    }\\n\\n    .ngx-image-compare__label.before {\\n      left: 20px;\\n    }\\n\\n    .ngx-image-compare__label.after {\\n      right: 20px;\\n    }\\n\\n    .dark .ngx-image-compare__label {\\n      background: rgba(15, 23, 42, 0.65);\\n      border-color: rgba(255, 255, 255, 0.08);\\n      color: #f1f5f9;\\n    }\\n\\n    /* Divider Handle styles */\\n    .ngx-image-compare__handle {\\n      position: absolute;\\n      z-index: 10;\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n      pointer-events: none;\\n      transition: box-shadow 0.2s ease;\\n    }\\n\\n    /* Horizontal orientation */\\n    .ngx-image-compare__handle:not(.vertical) {\\n      top: 0;\\n      bottom: 0;\\n      width: 2px;\\n      flex-direction: column;\\n      transform: translateX(-50%);\\n    }\\n\\n    /* Vertical orientation */\\n    .ngx-image-compare__handle.vertical {\\n      left: 0;\\n      right: 0;\\n      height: 2px;\\n      flex-direction: row;\\n      transform: translateY(-50%);\\n      cursor: ns-resize;\\n    }\\n\\n    .ngx-image-compare:has(.ngx-image-compare__handle.vertical) {\\n      cursor: ns-resize;\\n    }\\n\\n    /* Lines */\\n    .ngx-image-compare__line {\\n      flex-grow: 1;\\n      background: rgba(255, 255, 255, 0.9);\\n      box-shadow: 0 0 6px rgba(0, 0, 0, 0.2);\\n    }\\n\\n    .ngx-image-compare__handle:not(.vertical) .ngx-image-compare__line {\\n      width: 2px;\\n    }\\n\\n    .ngx-image-compare__handle.vertical .ngx-image-compare__line {\\n      height: 2px;\\n    }\\n\\n    /* Drag circle */\\n    .ngx-image-compare__circle {\\n      width: 36px;\\n      height: 36px;\\n      border-radius: 50%;\\n      background: rgba(255, 255, 255, 0.85);\\n      backdrop-filter: blur(8px);\\n      -webkit-backdrop-filter: blur(8px);\\n      border: 2px solid #ffffff;\\n      color: #0f172a;\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n      box-shadow: \\n        0 4px 10px rgba(0, 0, 0, 0.15),\\n        inset 0 1px 0 rgba(255, 255, 255, 0.8);\\n      z-index: 11;\\n      transition: all 0.2s cubic-bezier(0.2, 0.8, 0.2, 1);\\n    }\\n\\n    .ngx-image-compare:hover .ngx-image-compare__circle {\\n      transform: scale(1.08);\\n      box-shadow: \\n        0 0 0 4px rgba(255, 255, 255, 0.25),\\n        0 8px 16px rgba(0, 0, 0, 0.2);\\n    }\\n\\n    .ngx-image-compare.dragging .ngx-image-compare__circle {\\n      transform: scale(1.15);\\n      background: var(--primary-color, #3b82f6);\\n      border-color: var(--primary-color, #3b82f6);\\n      color: #ffffff;\\n      box-shadow: \\n        0 0 0 6px rgba(59, 130, 246, 0.25),\\n        0 12px 24px rgba(0, 0, 0, 0.25);\\n    }\\n\\n    .dark .ngx-image-compare__circle {\\n      background: rgba(15, 23, 42, 0.85);\\n      border-color: rgba(255, 255, 255, 0.1);\\n      color: #cbd5e1;\\n    }\\n\\n    .dark .ngx-image-compare.dragging .ngx-image-compare__circle {\\n      background: var(--primary-color, #3b82f6);\\n      border-color: var(--primary-color, #3b82f6);\\n      color: #ffffff;\\n    }\\n\\n    .handle-arrow-icon {\\n      transition: transform 0.2s ease;\\n    }\\n  "],"template":"<div\\n  class=\\"ngx-image-compare\\"\\n  [class.dark]=\\"theme() === \'dark\'\\"\\n  [class.dragging]=\\"isDragging()\\"\\n  [attr.id]=\\"id()\\"\\n  tabindex=\\"0\\"\\n  (keydown)=\\"onKeyDown($event)\\"\\n  aria-label=\\"Image comparison slider\\"\\n>\\n  \x3c!-- After Image (Background layer) --\x3e\\n  <div class=\\"ngx-image-compare__layer after\\">\\n    <img [src]=\\"afterImage()\\" class=\\"ngx-image-compare__image\\" alt=\\"After image\\" />\\n    @if (afterLabel()) {\\n      <div class=\\"ngx-image-compare__label after\\">{{ afterLabel() }}</div>\\n    }\\n  </div>\\n\\n  \x3c!-- Before Image (Overlay layer clipped dynamically) --\x3e\\n  <div\\n    class=\\"ngx-image-compare__layer before\\"\\n    [style.clipPath]=\\"clipPathStyle()\\"\\n  >\\n    <img [src]=\\"beforeImage()\\" class=\\"ngx-image-compare__image\\" alt=\\"Before image\\" />\\n    @if (beforeLabel()) {\\n      <div class=\\"ngx-image-compare__label before\\">{{ beforeLabel() }}</div>\\n    }\\n  </div>\\n\\n  \x3c!-- Drag Divider Handle --\x3e\\n  <div\\n    class=\\"ngx-image-compare__handle\\"\\n    [class.vertical]=\\"orientation() === \'vertical\'\\"\\n    [style.left.%]=\\"orientation() === \'horizontal\' ? sliderPos() : 50\\"\\n    [style.top.%]=\\"orientation() === \'vertical\' ? sliderPos() : 50\\"\\n  >\\n    <div class=\\"ngx-image-compare__line\\"></div>\\n    <div class=\\"ngx-image-compare__circle\\">\\n      <svg class=\\"handle-arrow-icon\\" viewBox=\\"0 0 24 24\\" width=\\"16\\" height=\\"16\\" fill=\\"none\\" stroke=\\"currentColor\\" stroke-width=\\"2.5\\">\\n        @if (orientation() === \'horizontal\') {\\n          <polyline points=\\"8 18 2 12 8 6\\" />\\n          <polyline points=\\"16 6 22 12 16 18\\" />\\n        } @else {\\n          <polyline points=\\"18 8 12 2 6 8\\" />\\n          <polyline points=\\"6 16 12 22 18 16\\" />\\n        }\\n      </svg>\\n    </div>\\n    <div class=\\"ngx-image-compare__line\\"></div>\\n  </div>\\n</div>\\n","templateUrl":[],"viewProviders":[],"hostDirectives":[],"inputsClass":[{"name":"afterImage","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":271,"required":true},{"name":"afterLabel","defaultValue":"\'After\'","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":273,"required":false},{"name":"beforeImage","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":270,"required":true},{"name":"beforeLabel","defaultValue":"\'Before\'","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":272,"required":false},{"name":"id","defaultValue":"\'ngx-img-compare-\' + Math.random().toString(36).substring(2, 9)","deprecated":false,"deprecationMessage":"","type":"string","indexKey":"","optional":false,"description":"","line":277,"required":false},{"name":"orientation","defaultValue":"\'horizontal\'","deprecated":false,"deprecationMessage":"","type":"\\"horizontal\\" | \\"vertical\\"","indexKey":"","optional":false,"description":"","line":275,"required":false},{"name":"startOffset","defaultValue":"50","deprecated":false,"deprecationMessage":"","type":"number","indexKey":"","optional":false,"description":"","line":274,"required":false},{"name":"theme","defaultValue":"\'light\'","deprecated":false,"deprecationMessage":"","type":"\\"light\\" | \\"dark\\"","indexKey":"","optional":false,"description":"","line":276,"required":false}],"outputsClass":[],"propertiesClass":[{"name":"clipPathStyle","defaultValue":"computed(() => {\\n    const pos = this.sliderPos();\\n    if (this.orientation() === \'horizontal\') {\\n      return `inset(0 ${100 - pos}% 0 0)`;\\n    } else {\\n      return `inset(0 0 ${100 - pos}% 0)`;\\n    }\\n  })","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":284},{"name":"isDragging","defaultValue":"signal<boolean>(false)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":281},{"name":"sliderPos","defaultValue":"signal<number>(50)","deprecated":false,"deprecationMessage":"","type":"unknown","indexKey":"","optional":false,"description":"","line":280}],"methodsClass":[{"name":"ngOnInit","args":[],"optional":false,"returnType":"void","typeParameters":[],"line":293,"deprecated":false,"deprecationMessage":""},{"name":"onDragEnd","args":[],"optional":false,"returnType":"void","typeParam